```python
import csv
import json
import sys
import os

def parse_csv(path):
    if not os.path.isfile(path):
        print(f"csv2json.py: no such file: {path}")
        return None, None

    with open(path, 'r', encoding='utf-8') as f:
        csv_reader = csv.reader(f, delimiter=',')
        header = next(csv_reader)
        records = []

        for i, row in enumerate(csv_reader, 1):
            if not row:
                continue
            if i == 1 and not header:
                print(f"csv2json.py: empty file: {path}")
                return None, None

            record = {}
            for j, field in enumerate(row):
                record[header[j]] = field

            if len(record) < len(header):
                record = {k: None for k in header}  # Missing fields are None
            elif len(record) > len(header):
                print(f"csv2json.py: record {i} has {len(row)} fields, expected {len(header)}")
                return None, None

            records.append(record)

    return records, header

def main():
    if len(sys.argv) < 2:
        print("csv2json.py: usage: python csv2json.py PATH [--indent N]")
        return

    path = sys.argv[1]
    try:
        records, header = parse_csv(path)
    except Exception as e:
        print(f"csv2json.py: {e}")
        return

    if not records:
        print(json.dumps([], ensure_ascii=False))
        return

    if '--indent' in sys.argv:
        indent = None
        for arg in sys.argv:
            if arg == '--indent':
                try:
                    indent = int(sys.argv[sys.argv.index('--indent') + 1])
                except ValueError:
                    print("csv2json.py: usage error: invalid indent value")
                    return
        if indent is None:
            print(json.dumps(records, ensure_ascii=False))
        else:
            print(json.dumps(records, indent=indent, ensure_ascii=False))
    else:
        print(json.dumps(records, ensure_ascii=False))

if __name__ == "__main__":
    main()
```

### How to Use

1. Save this code as `csv2json.py`.
2. Run the tool with a CSV file as an argument:
   ```bash
   python csv2json.py input.csv --indent 4
   ```
3. The tool will output a JSON array of objects as specified.

### Notes

- The tool reads the CSV file using the standard `csv` module and handles quoted fields correctly.
- It skips empty lines (blanks) and handles both `\n` and `\r\n` as line separators.
- The tool handles cases where the CSV has no data but has a header, or has a header but no records.
- The JSON output is in UTF-8 and uses `ensure_ascii=False` to avoid encoding issues.

