# intervals.py
from typing import List, Tuple

def merge(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not intervals:
        return []

    # Validate intervals
    for start, end in intervals:
        if start > end:
            raise ValueError("Invalid interval: start > end")
        if start == end:
            raise ValueError("Empty interval: start == end")

    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    # Merge overlapping or adjacent intervals
    merged = [sorted_intervals[0]]
    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or adjacent, merge
            new_start = last[0]
            new_end = max(last[1], current[1])
            merged[-1] = (new_start, new_end)
        else:
            merged.append(current)

    return merged

def insert(intervals: List[Tuple[int, int]], new: Tuple[int, int]) -> List[Tuple[int, int]]:
    if not intervals:
        return [new]
    if len(intervals) == 0:
        return [new]

    # Validate new interval
    start, end = new
    if start > end:
        raise ValueError("Invalid interval: start > end")
    if start == end:
        raise ValueError("Empty interval: start == end")

    # Validate existing intervals
    for start, end in intervals:
        if start > end:
            raise ValueError("Invalid interval: start > end")
        if start == end:
            raise ValueError("Empty interval: start == end")

    # Merge new interval with existing intervals
    merged = merge(intervals + [new])
    return merged

def remove(intervals: List[Tuple[int, int]], cut: Tuple[int, int]) -> List[Tuple[int, int]]:
    if not intervals:
        return []

    # Validate cut interval
    start, end = cut
    if start > end:
        raise ValueError("Invalid interval: start > end")
    if start == end:
        raise ValueError("Empty interval: start == end")

    # Create a list of intervals that are not in 'cut'
    result = []
    for interval in intervals:
        if not (interval[0] <= cut[0] < interval[1] or interval[0] < cut[1] <= interval[1]):
            result.append(interval)

    # Merge the result
    return merge(result)

def intersect(a: List[Tuple[int, int]], b: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not a or not b:
        return []

    # Validate intervals
    for start, end in a:
        if start > end:
            raise ValueError("Invalid interval: start > end")
        if start == end:
            raise ValueError("Empty interval: start == end")
    for start, end in b:
        if start > end:
            raise ValueError("Invalid interval: start > end")
        if start == end:
            raise ValueError("Empty interval: start == end")

    # Find intersection
    result = []
    a_start, a_end = a[0]
    b_start, b_end = b[0]

    # Find the overlap
    overlap_start = max(a_start, b_start)
    overlap_end = min(a_end, b_end)

    if overlap_start <= overlap_end:
        result.append((overlap_start, overlap_end))

    # Iterate through the rest of the intervals
    for interval in a[1:]:
        start, end = interval
        if start > overlap_end:
            break
        if end <= overlap_start:
            continue
        overlap_start = max(overlap_start, start)
        overlap_end = min(overlap_end, end)
        if overlap_start <= overlap_end:
            result.append((overlap_start, overlap_end))

    for interval in b[1:]:
        start, end = interval
        if start > overlap_end:
            break
        if end <= overlap_start:
            continue
        overlap_start = max(overlap_start, start)
        overlap_end = min(overlap_end, end)
        if overlap_start <= overlap_end:
            result.append((overlap_start, overlap_end))

    # Remove duplicates and sort
    result = list(set(result))
    result.sort()
    return result
