# lru.py
from typing import Dict, List, Optional, Tuple
from collections import OrderedDict
import time

class LRUCache:
    def __init__(self, capacity: int, ttl: Optional[float] = None, clock: callable = time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.cache = OrderedDict()
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def get(self, key: str, default: Optional[str] = None) -> Optional[str]:
        if key in self.cache:
            self.cache.move_to_end(key)
            self.hits += 1
            return self.cache[key]
        self.misses += 1
        return default

    def put(self, key: str, value: str):
        if key in self.cache:
            self.cache[key] = value
            self.cache.move_to_end(key)
            self.hits += 1
        else:
            if self.ttl is not None:
                time_stored = self.clock()
                if self.ttl <= 0:
                    # Entry is not expired, do not evict
                    self.cache[key] = value
                    self.cache.move_to_end(key)
                    self.hits += 1
                else:
                    # Calculate time stored
                    time_stored = self.clock()
                    # Check if entry is expired
                    if time_stored - self.cache[key][1] >= self.ttl:
                        self.expirations += 1
                        # Remove the entry
                        self.cache.pop(key)
                        # If the cache is now empty, evict
                        if len(self.cache) == 0:
                            self.evictions += 1
                            # Evict the LRU key
                            lru_key = self.cache.popitem(last=False)
                            return lru_key[0]
                        else:
                            # Move the key to the end
                            self.cache.move_to_end(key)
            else:
                # Entry is not expired, add to cache
                if len(self.cache) >= self.capacity:
                    # Evict the LRU key
                    lru_key = self.cache.popitem(last=False)
                    self.evictions += 1
                    # Move the new key to the end
                    self.cache[key] = value
                    self.cache.move_to_end(key)
                else:
                    self.cache[key] = value
                    self.cache.move_to_end(key)
                    self.hits += 1

        return None

    def len(self) -> int:
        return len(self.cache)

    def __contains__(self, key: str) -> bool:
        return key in self.cache

    def keys(self) -> List[str]:
        return list(self.cache.keys())

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        new_capacity = capacity
        evicted = []
        if self.capacity != new_capacity:
            # Evict the least recently used keys
            while len(self.cache) > new_capacity:
                lru_key = self.cache.popitem(last=False)
                evicted.append(lru_key[0])
        self.capacity = new_capacity
        return evicted

    def stats(self) -> dict:
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations
        }
