# ini.py
from typing import List, Dict, Optional, Any, Union
from collections import defaultdict
import re

class ParseError(ValueError):
    def __init__(self, lineno: int, message: str):
        super().__init__(message)
        self.lineno = lineno

class Config:
    def __init__(self):
        self.sections = defaultdict(dict)
        self.current_section = None
        self.line_number = 0

    def parse(self, text: str) -> 'Config':
        self.line_number = 0
        self.sections = defaultdict(dict)
        self.current_section = None
        lines = text.strip('\n').splitlines()
        for line in lines:
            self.line_number += 1
            if self._is_blank(line):
                continue
            if self._is_comment(line):
                continue
            if self._is_section_header(line):
                self._parse_section(line)
            elif self._is_key_line(line):
                self._parse_key_line(line)
            else:
                self._handle_invalid_line(line)
        return self

    def _is_blank(self, line: str) -> bool:
        return line.strip() == ''

    def _is_comment(self, line: str) -> bool:
        return line.strip().startswith('#') or line.strip().startswith(';')

    def _is_section_header(self, line: str) -> bool:
        line = line.strip()
        if not line:
            return False
        if not line.startswith('[') or not line.endswith(']'):
            return False
        name = line[1:-1].strip()
        if not name:
            return False
        return not self.current_section and name != ''

    def _is_key_line(self, line: str) -> bool:
        line = line.strip()
        if not line:
            return False
        if not line.startswith('key ='):
            return False
        if not line.startswith('key ='):
            return False
        return not self.current_section

    def _parse_section(self, line: str):
        if not self.current_section:
            self.current_section = line[1:-1].strip()
        else:
            raise ParseError(self.line_number, f"Duplicate section header: {self.current_section}")

    def _parse_key_line(self, line: str):
        if not self.current_section:
            raise ParseError(self.line_number, f"Key line before section header")
        parts = line.split('=', 1)
        if len(parts) != 2:
            raise ParseError(self.line_number, f"Missing '=' in key line")
        key = parts[0].strip()
        value = parts[1].strip()
        if not key:
            raise ParseError(self.line_number, f"Empty key")
        if not value:
            value = ''
        self.sections[self.current_section][key] = value

    def _handle_invalid_line(self, line: str):
        line = line.strip()
        if not line:
            raise ParseError(self.line_number, f"Empty line")
        if not line.startswith('key =') and not self.current_section:
            raise ParseError(self.line_number, f"Invalid line: {line}")
        if self.current_section and not line.startswith('key ='):
            raise ParseError(self.line_number, f"Non-key line in section {self.current_section}")

    def sections(self) -> List[str]:
        return list(self.sections.keys())

    def keys(self, section: str) -> List[str]:
        if section not in self.sections:
            raise KeyError(f"Section {section} not found")
        return list(self.sections[section].keys())

    def get(self, section: str, key: str, default: Any = None) -> Union[str, None]:
        if section not in self.sections:
            return default
        if key not in self.sections[section]:
            return default
        return self.sections[section][key]

    def getint(self, section: str, key: str, default: int = 0) -> int:
        value = self.get(section, key, default)
        if not value:
            return default
        if not value.isdigit():
            raise ValueError(f"Invalid integer value for key {key}: {value}")
        return int(value)

    def getbool(self, section: str, key: str, default: bool = False) -> bool:
        value = self.get(section, key, default)
        if not value:
            return default
        value = value.lower()
        if value in ('true', 'yes', 'on', '1'):
            return True
        if value in ('false', 'no', 'off', '0'):
            return False
        raise ValueError(f"Invalid boolean value for key {key}: {value}")

    def getlist(self, section: str, key: str, default: List[str] = None) -> List[str]:
        value = self.get(section, key, default)
        if not value:
            return default
        parts = value.split(',')
        result = []
        for part in parts:
            stripped = part.strip()
            if stripped:
                result.append(stripped)
        return result if result else default
