# semver.py
from typing import Optional, Tuple, List, Set
from dataclasses import dataclass
from functools import lru_cache
import re
import sys
import string

# Constants for SemVer 2.0.0
SEMVER_VERSION_PATTERN = re.compile(r'^(\d+)(\.\d+)(\.\d+)$')
SEMVER_PRERELEASE_PATTERN = re.compile(r'^-(\w+)(\.\w+)*$')
SEMVER_BUILD_PATTERN = re.compile(r'^+(\w+)(\.\w+)*$')

# Constants for comparison
COMPARATOR_OP = {
    '>=': '>=',
    '>': '>',
    '<=': '<=',
    '<': '<',
    '==': '==',
    '!=': '!='
}

# Constants for version comparison
COMPARATOR_TYPES = {
    '>=': '>=',
    '>': '>',
    '<=': '<=',
    '<': '<',
    '==': '==',
    '!=': '!='
}

# Constants for version comparison
COMPARATOR_REGEX = {
    '>=': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
    '>': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
    '<=': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
    '<': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
    '==': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
    '!=': r'^(?:\d+\.?\d*)?(\.\d+)(?:\.\d+)?$',  # Matches version without pre-release
}

@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: Tuple[str, ...]
    build: Tuple[str, ...]

    def __str__(self) -> str:
        parts = []
        if self.major > 0:
            parts.append(f"{self.major}")
        if self.minor > 0:
            parts.append(f".{self.minor}")
        if self.patch > 0:
            parts.append(f".{self.patch}")
        if parts:
            parts.append("".join(parts))
        if self.prerelease:
            parts.append(f"-{'.'.join(self.prerelease)}")
        if self.build:
            parts.append(f"+{'.'.join(self.build)}")
        return "".join(parts)

    def __lt__(self, other: 'Version') -> bool:
        if self is other:
            return False
        if not isinstance(other, Version):
            return NotImplemented
        # Compare major
        if self.major < other.major:
            return True
        if self.major > other.major:
            return False
        # Compare minor
        if self.minor < other.minor:
            return True
        if self.minor > other.minor:
            return False
        # Compare patch
        if self.patch < other.patch:
            return True
        if self.patch > other.patch:
            return False
        # Compare prerelease
        if len(self.prerelease) < len(other.prerelease):
            return True
        if len(self.prerelease) > len(other.prerelease):
            return False
        for i in range(len(self.prerelease)):
            if self.prerelease[i] < other.prerelease[i]:
                return True
            if self.prerelease[i] > other.prerelease[i]:
                return False
        return False

    def __le__(self, other: 'Version') -> bool:
        return self < other or self == other

    def __gt__(self, other: 'Version') -> bool:
        return not self <= other

    def __ge__(self, other: 'Version') -> bool:
        return not self < other

    def __eq__(self, other: 'Version') -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch and \
               self.prerelease == other.prerelease and self.build == other.build

    def __ne__(self, other: 'Version') -> bool:
        return not self == other

    def bump(self, kind: str) -> 'Version':
        if kind == 'major':
            new_major = self.major + 1
            new_minor = 0
            new_patch = 0
            new_prerelease = []
            new_build = []
            return Version(
                new_major,
                new_minor,
                new_patch,
                new_prerelease,
                new_build
            )
        elif kind == 'minor':
            new_major = self.major
            new_minor = self.minor + 1
            new_patch = 0
            new_prerelease = []
            new_build = []
            return Version(
                new_major,
                new_minor,
                new_patch,
                new_prerelease,
                new_build
            )
        elif kind == 'patch':
            new_major = self.major
            new_minor = self.minor
            new_patch = self.patch + 1
            new_prerelease = []
            new_build = []
            return Version(
                new_major,
                new_minor,
                new_patch,
                new_prerelease,
                new_build
            )
        else:
            raise ValueError(f"Invalid bump kind: {kind}")

    def satisfies(self, spec: str) -> bool:
        # Split spec into comparators
        comparators = spec.split()
        if not comparators:
            return True
        for comparator in comparators:
            if not comparator:
                continue
            # Parse comparator
            if comparator.startswith('^'):
                comparator = comparator[1:]
            elif comparator.startswith('~'):
                comparator = comparator[1:]
            # Check if comparator is a valid version
            if not self._is_valid_version(comparator):
                raise ValueError("Invalid spec")
            # Compare
            if not self._compare_version(comparator):
                return False
        return True

    def _is_valid_version(self, version: str) -> bool:
        # Check if version is a valid SemVer version
        if not version:
            return False
        # Check if version is a valid version string
        if not re.match(r'^(\d+)(\.\d+)(\.\d+)$', version):
            return False
        # Check if version is a valid pre-release
        if '-' in version:
            if not re.match(r'^-((\w+)(\.\w+)*$)', version):
                return False
        # Check if version is a valid build
        if '+' in version:
            if not re.match(r'^+(\w+)(\.\w+)*$', version):
                return False
        return True

    def _compare_version(self, version: str) -> bool:
        # Compare version with the given version
        # Compare by precedence: major, minor, patch, then prerelease, then build
        # Handle partial versions
        if '.' in version:
            # Partial version, e.g., '1.2' → '1.2.0'
            parts = version.split('.')
            if len(parts) < 3:
                parts += ['0'] * (3 - len(parts))
            major, minor, patch = parts
        else:
            # Full version, e.g., '1.2.3'
            parts = version.split('.')
            if len(parts) < 3:
                parts += ['0'] * (3 - len(parts))
            major, minor, patch = parts
        # Convert to integers
        major = int(major)
        minor = int(minor)
        patch = int(patch)
        # Compare by major
        if self.major < major:
            return True
        if self.major > major:
            return False
        # Compare by minor
        if self.minor < minor:
            return True
        if self.minor > minor:
            return False
        # Compare by patch
        if self.patch < patch:
            return True
        if self.patch > patch:
            return False
        # Compare prerelease
        if len(self.prerelease) < len(version.split('-')[1]):
            return True
        if len(self.prerelease) > len(version.split('-')[1]):
            return False
        for i in range(len(self.prerelease)):
            prerelease_left = self.prerelease[i]
            prerelease_right = version.split('-')[1][i]
            if prerelease_left < prerelease_right:
                return True
            if prerelease_left > prerelease_right:
                return False
        # Compare build
        if len(self.build) < len(version.split('+')[1]):
            return True
        if len(self.build) > len(version.split('+')[1]):
            return False
        for i in range(len(self.build)):
            build_left = self.build[i]
            build_right = version.split('+')[1][i]
            if build_left < build_right:
                return True
            if build_left > build_right:
                return False
        return False
