                return fractions.Fraction(left.numerator * right.denominator + right.numerator * left.denominator, left.denominator * right.denominator)
    return evaluate_sub(tokens)

def evaluate_token(token: str, variables: Optional[Dict[str, Union[int, fractions.Fraction]]] = None) -> fractions.Fraction:
    # Evaluate a single token
    if token in variables:
        return variables[token]
    if token.isdigit():
        return fractions.Fraction(int(token), 1)
    if token == '-':
        return fractions.Fraction(0, 1)
    if token == '+':
        return fractions.Fraction(1, 1)
    if token == '*':
        return fractions.Fraction(1, 1)
    if token == '/':
        return fractions.Fraction(1, 1)
    if token == '(':
        return fractions.Fraction(0, 1)
    if token == ')':
        return fractions.Fraction(0, 1)
    if token == ',':
        return fractions.Fraction(0, 1)
    if token == '(':
        func_name, args = parse_function_call(tokens)
        return evaluate_function(func_name, args, variables)
    if token == '**':
        return handle_exponent(tokens)
    raise CalcError(f"Unknown token: {token}", 0)
