def is_business_day(d, *, holidays=(), weekend=(5, 6)) -> bool:
    """
    Check if a given date is a business day.
    """
    if not isinstance(d, date):
        raise ValueError("Argument 'd' must be a date object")

    # Check if the date is a weekend
    if d.weekday() in weekend:
        return False

    # Check if the date is in holidays
    if d in holidays:
        return False

    return True

def business_days_between(start, end, *, include_start=True, include_end=False, holidays=(), weekend=(5, 6)) -> int:
    """
    Count the number of business days between start and end, inclusive.
    """
    if not isinstance(start, date):
        raise ValueError("Argument 'start' must be a date object")
    if not isinstance(end, date):
        raise ValueError("Argument 'end' must be a date object")

    if start > end:
        raise ValueError("start must be less than or equal to end")

    # Calculate the number of business days
    count = 0
    current = start

    while current <= end:
        if is_business_day(current, holidays=holidays, weekend=weekend):
            count += 1
        current += timedelta(days=1)

    if include_start:
        count += 1 if is_business_day(start, holidays=holidays, weekend=weekend) else 0
    if include_end:
        count += 1 if is_business_day(end, holidays=holidays, weekend=weekend) else 0

    return count

def add_business_days(d, n, *, holidays=(), weekend=(5, 6)) -> date:
    """
    Add n business days to a date, considering weekends and holidays.
    """
    if not isinstance(d, date):
        raise ValueError("Argument 'd' must be a date object")

    if n == 0:
        return d if is_business_day(d, holidays=holidays, weekend=weekend) else date(1, 1, 1)  # default date

    # For n > 0, find the n-th business day after d
    # For n < 0, find the |n|-th business day before d
    # Ensure we don't count d itself if it's not a business day

    # Helper function to get the next business day
    def next_business_day(date):
        while True:
            if is_business_day(date, holidays=holidays, weekend=weekend):
                return date
            date += timedelta(days=1)

    # Handle positive n
    if n > 0:
        current = d
        for _ in range(n):
            current = next_business_day(current)
    else:
        # Handle negative n
        current = d
        for _ in range(-n):
            current = next_business_day(current)

    return current
