"""
A Python module to format a GitHub-flavoured Markdown table.
"""

def format_table(rows, headers, align=None) -> str:
    if not headers:
        raise ValueError("Headers must be a non-empty sequence.")
    if not rows:
        raise ValueError("Rows must be an iterable of non-empty sequences.")

    if align is None:
        align = ['left'] * len(headers)

    if len(align) != len(headers):
        raise ValueError("Align must have the same length as headers.")

    # Validate align values
    for a in align:
        if a not in ['left', 'right', 'center']:
            raise ValueError("Align must be 'left', 'right', or 'center'.")

    # Validate row and header lengths
    if len(rows[0]) != len(headers):
        raise ValueError("Each row must have exactly one cell per header.")

    # Determine column widths
    column_widths = [0] * len(headers)
    for col in range(len(headers)):
        header_text = str(headers[col])
        row_texts = [str(row[col]) for row in rows]
        max_width = max(len(escape_text(t)) for t in [header_text] + row_texts)
        column_widths[col] = max_width if max_width >= 3 else 3

    # Escape text for Markdown
    def escape_text(text):
        return text.replace('\\', '\\\\').replace('|', '\\|')

    # Build the table
    table = []

    # Header line
    header_line = "| " + " | ".join(escape_text(headers[i]).ljust(column_widths[i]) for i in range(len(headers))) + " |"
    table.append(header_line)

    # Separator line
    separator_line = ""
    for col in range(len(headers)):
        if align[col] == 'left':
            separator_line += ":----"
        elif align[col] == 'right':
            separator_line += "----:"
        else:  # center
            separator_line += ":-"
        separator_line += " |"
    separator_line = separator_line[:-1]  # Remove the last ' |'
    table.append(separator_line)

    # Row lines
    for row in rows:
        row_line = "| " + " | ".join(
            escape_text(escape_text(str(row[i]))).ljust(column_widths[i]) for i in range(len(headers))
        ) + " |"
        table.append(row_line)

    return "\n".join(table)
