from typing import List

def diff(a: List[str], b: List[str]) -> List[str]:
    def lcs_length(x: List[str], y: List[str]) -> int:
        m, n = len(x), len(y)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if x[i-1] == y[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])
        return dp[m][n]

    i = j = 0
    result = []

    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            result.append(' ' + a[i])
            i += 1
            j += 1
        else:
            # Compare LCS lengths
            lcs_a = lcs_length(a[i:], b[j:])
            lcs_b = lcs_length(a[i:], b[j+1:])

            if lcs_a >= lcs_b:
                result.append('-' + a[i])
                i += 1
            else:
                result.append('+ ' + b[j])
                j += 1

    # Handle remaining elements
    while i < len(a):
        result.append('-' + a[i])
        i += 1
    while j < len(b):
        result.append('+ ' + b[j])
        j += 1

    return result
