    # Create a dependency set
    dependencies = set()
    for node in graph:
        dependencies.update(graph[node])

    # Build in-degree count for each node
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for dep in graph[node]:
            in_degree[dep] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for node in graph:
        if in_degree[node] == 0:
            queue.append(node)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for dep in graph[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)

    # Check for cycles
    if any(in_degree[node] > 0 for node in graph):
        raise CycleError([node for node in graph if in_degree[node] > 0])

    # If no nodes were processed, it's an empty graph
    if not result:
        return []

    # Sort by lexicographical order in case of ties
    result.sort()
    return result
