def levels(graph: Dict[str, List[str]]) -> List[List[str]]:
    if not graph:
        return []

    # Compute levels for each node
    levels_dict = {node: 0 for node in graph}
    queue = deque()

    # Initialize nodes with no dependencies
    for node in graph:
        if not graph[node]:
            queue.append(node)
            levels_dict[node] = 0

    while queue:
        node = queue.popleft()
        for dep in graph[node]:
            levels_dict[dep] = max(levels_dict[dep], levels_dict[node] + 1)
            if levels_dict[dep] == 0:
                queue.append(dep)

    # Sort levels by their value and extract the lists
    level_lists = []
    for level in sorted(levels_dict.keys(), key=lambda x: levels_dict[x]):
        level_lists.append([node for node in sorted(level_list if level_list else [])])

    return level_lists

def subgraph_order(graph: Dict[str, List[str]], targets: List[str]) -> List[str]:
    if not targets:
        return []

    # Check if all targets are in the graph
    for target in targets:
        if target not in graph:
            raise KeyError(f"Target {target} not in graph")

    # Build a subgraph consisting of the targets and their dependencies
    subgraph = defaultdict(list)
    visited = set()

    # Add all targets and their dependencies
    for target in targets:
        subgraph[target].append(target)
        for dep in graph[target]:
            if dep not in visited:
                subgraph[dep].append(dep)
                visited.add(dep)

    # Build adjacency list for the subgraph
    adj = defaultdict(list)
    for node in subgraph:
        for dep in subgraph[node]:
            adj[dep].append(node)

    # Perform topological sort on the subgraph
    in_degree = {node: 0 for node in subgraph}
    for node in subgraph:
        for dep in subgraph[node]:
            in_degree[dep] += 1

    queue = deque()
    for node in subgraph:
        if in_degree[node] == 0:
            queue.append(node)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for dep in subgraph[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)

    # Check for cycles in the subgraph
    if any(in_degree[node] > 0 for node in subgraph):
        raise CycleError([node for node in subgraph if in_degree[node] > 0])

    # Return the result in the order of topological sort
    return result
