def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    # Split the expression into fields
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly five fields")

    # Parse each field
    minute_field = parse_field(fields[0])
    hour_field = parse_field(fields[1])
    day_field = parse_field(fields[2])
    month_field = parse_field(fields[3])
    day_of_week_field = parse_field(fields[4])

    # Find the next time that matches all fields
    next_time = after
    while True:
        if is_match(minute_field, next_time.minute) and \
           is_match(hour_field, next_time.hour) and \
           is_match(day_field, next_time.day) and \
           is_match(month_field, next_time.month) and \
           is_match(day_of_week_field, next_time.weekday()):
            return next_time
        # Move to the next minute
        next_time += timedelta(minutes=1)

def parse_field(field: str) -> tuple:
    # Split the field into items
    items = field.split(',')
    if not items:
        raise ValueError("Field cannot be empty")

    parsed = []
    for item in items:
        item = item.strip()
        if item == '*':
            parsed.append('*')
        elif item == 'N':
            # Check if it's a valid N
            if not item.isdigit():
                raise ValueError("Invalid N value")
            parsed.append(item)
        elif item.startswith('/'):
            # Handle /S or A-B/S
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError("Invalid /S format")
            if parts[0] == 'A' and parts[1] == 'B':
                # A-B/S
                if not parts[1].isdigit():
                    raise ValueError("Invalid A-B/S format")
                start = int(parts[0])
                end = int(parts[1])
                if start > end:
                    raise ValueError("A must not be greater than B")
                parsed.append(f"{'/'.join(parts)}")
            else:
                # /S
                if not parts[1].isdigit():
                    raise ValueError("Invalid /S format")
                step = int(parts[1])
                if step <= 0:
                    raise ValueError("Step must be positive")
                parsed.append(f"{'/'.join(parts)}")
        else:
            # Check if it's a range A-B
            if not item.isdigit():
                raise ValueError("Invalid range format")
            start = int(item)
            end = int(item)
            if start > end:
                raise ValueError("A must not be greater than B")
            parsed.append(f"{start}-{end}")
    return tuple(parsed)

def is_match(field: tuple, value: int) -> bool:
    if field[0] == '*':
        return True
    elif field[0] == 'N':
        if not (1 <= int(field[1]) <= 59):
            raise ValueError("Invalid N value")
        return int(field[1]) == value
    elif field[0] == '/':
        # Handle /S or A-B/S
        if field[1] == 'S':
            # /S: every S-th value of *
            if field[2] == 'A' and field[3] == 'B':
                # A-B/S
                if not field[2].isdigit() or not field[3].isdigit():
                    raise ValueError("Invalid A-B/S format")
                start = int(field[2])
                end = int(field[3])
                if start > end:
                    raise ValueError("A must not be greater than B")
                return (start + (end - start) * (value - start) // (end - start)) == value
            else:
                # /S: every S-th value of *
                if not field[2].isdigit():
                    raise ValueError("Invalid /S format")
                step = int(field[2])
                if step <= 0:
                    raise ValueError("Step must be positive")
                return (value - start) % step == 0
        else:
            # Invalid format
            raise ValueError("Invalid /S format")
    else:
        # Check if it's a range A-B
        if field[0] != 'A' or field[1] != 'B':
            raise ValueError("Invalid range format")
        start = int(field[0])
        end = int(field[1])
        if start > end:
            raise ValueError("A must not be greater than B")
        return start <= value <= end
