class PathError(LookupError):
    def __init__(self, path: str):
        super().__init__(path)
        self.path = path

def parse(path: str) -> List[Union[str, int]]:
    """
    Parse a path string into segments, names, and indices.
    Returns a list of segments in order, where:
    - names are strings
    - indices are integers
    - quoted keys are strings
    """
    segments = []
    i = 0
    while i < len(path):
        if path[i] == '"':
            # Handle quoted key
            j = i + 1
            while j < len(path) and path[j] != '"':
                j += 1
            if j >= len(path):
                raise PathError(path)
            key = path[i+1:j]
            segments.append(key)
            i = j + 1
        elif path[i] == '[':
            # Handle list index
            if i + 1 >= len(path) or path[i+1] != ']':
                raise PathError(path)
            start = i + 1
            while i < len(path) and path[i] != ']':
                i += 1
            if i >= len(path):
                raise PathError(path)
            index = parse_index(path[start:i])
            segments.append(index)
            i = i + 1
        elif path[i] == '.':
            # Skip dot if it's part of a name
            if i + 1 < len(path) and path[i+1] != '[':
                i += 1
            else:
                raise PathError(path)
        else:
            # Handle regular name
            j = i
            while j < len(path) and path[j] not in ('[', ']', '"', '.'):
                j += 1
            if j == i:
                # Bare name
                segments.append(path[i:j])
                i = j
            else:
                # Name with a segment
                name = path[i:j]
                segments.append(name)
                i = j
    return segments

def parse_index(s: str) -> int:
    """
    Parse an index from a string like "[1.5]" or "[x]" into an integer.
    """
    if s[0] == '[' and s[-1] == ']':
        # Handle [N] where N is an integer
        if not s[1:].isdigit():
            raise PathError(s)
        return int(s[1:])
    # Handle [N] where N is a negative number
    if s[0] == '[' and s[-1] == ']':
        if not s[1:].isdigit():
            raise PathError(s)
        return int(s[1:])
    # Handle [x] where x is a string
    if s[0] == '[' and s[-1] == ']':
        # Check if the middle part is a valid integer
        if not s[1:].isdigit():
            raise PathError(s)
        return int(s[1:])
    raise PathError(s)

def get(obj: Union[Mapping, list, tuple, dict, str], path: str, default: Optional[any] = None) -> any:
    """
    Follow the path from `obj` and return the value it reaches.
    Returns `default` if the value is missing, and raises `PathError` if none was passed.
    """
    segments = parse(path)
    current = obj
    for segment in segments:
        if isinstance(current, Mapping):
            if segment in current:
                current = current[segment]
            else:
                if default is not None:
                    return default
                else:
                    raise PathError(path)
        elif isinstance(current, list):
            if isinstance(segment, int):
                if segment < 0:
                    segment = len(current) + segment
                if segment < 0 or segment >= len(current):
                    if default is not None:
                        return default
                    else:
                        raise PathError(path)
                current = current[segment]
            else:
                if default is not None:
                    return default
                else:
                    raise PathError(path)
        elif isinstance(current, str):
            if segment in current:
                current = current[segment]
            else:
                if default is not None:
                    return default
                else:
                    raise PathError(path)
        else:
            if default is not None:
                return default
            else:
                raise PathError(path)
    return current
