    """
    segments = parse(path)
    if not segments:
        raise PathError(path)
    if WILDCARD in segments:
        raise PathError(path)
    current = obj
    for i, segment in enumerate(segments):
        if isinstance(current, Mapping):
            if segment in current:
                # Continue to next segment
                current = current[segment]
            else:
                # Skip this segment
                if i + 1 < len(segments):
                    if isinstance(segments[i+1], int):
                        # The parent is a list, but the segment is a key
                        raise PathError(path)
                    else:
                        # The parent is a dict, but the segment is a list
                        raise PathError(path)
                else:
                    # No more segments, return the value
                    if i == len(segments) - 1:
                        if isinstance(current, dict):
                            return current.pop(segment, None)
                        elif isinstance(current, list):
                            return current.pop(segment, None)
                        else:
