                break
        elif isinstance(current, list):
            if isinstance(segment, int):
                if segment < 0:
                    segment = len(current) + segment
                if segment < 0 or segment >= len(current):
                    raise PathError(path)
                current.pop(segment)
            else:
                raise PathError(path)
        elif isinstance(current, str):
            raise PathError(path)
        else:
            raise PathError(path)
    return current
