from typing import List, Tuple, Union
from fractions import Fraction
from typing import Optional
from collections import defaultdict

class MatrixError(Exception):
    pass

class ShapeError(MatrixError):
    pass

class SingularMatrix(MatrixError):
    pass

def det(m: List[List[Fraction]]) -> Fraction:
    """Compute the determinant of a square matrix."""
    if not isinstance(m, list):
        raise ShapeError("Input must be a list of lists")
    if not m:
        raise ShapeError("Matrix is empty")
    n = len(m)
    if not all(len(row) == n for row in m):
        raise ShapeError("Matrix must have consistent row lengths")

    if n == 0:
        return Fraction(0)

    if n == 1:
        return m[0][0]

    # Using Gaussian elimination
    matrix = [row.copy() for row in m]
    n = len(matrix)
    for i in range(n):
        pivot = matrix[i][i]
        if pivot == Fraction(0):
            # Swap rows to find a non-zero pivot
            for j in range(i + 1, n):
                if matrix[j][i] != Fraction(0):
                    matrix[i], matrix[j] = matrix[j], matrix[i]
                    pivot = matrix[i][i]
                    break
            if pivot == Fraction(0):
                raise SingularMatrix("Matrix is singular")
        # Make all rows below the current row have 0 in the current column
        for j in range(i + 1, n):
            factor = matrix[j][i] / pivot
            for k in range(i, n):
                matrix[j][k] = matrix[j][k] - factor * matrix[i][k]

    # Compute the determinant
    det_val = Fraction(1)
    for i in range(n):
        det_val *= matrix[i][i]
    return det_val

def inverse(m: List[List[Fraction]]) -> List[List[Fraction]]:
    """Compute the inverse of a square matrix."""
    if not isinstance(m, list):
        raise ShapeError("Input must be a list of lists")
    if not m:
        raise ShapeError("Matrix is empty")
    n = len(m)
    if not all(len(row) == n for row in m):
        raise ShapeError("Matrix must have consistent row lengths")

    if n == 0:
        raise ShapeError("Matrix is empty")

    # Check if the matrix is singular
    det = det(m)
    if det == Fraction(0):
        raise SingularMatrix("Matrix is singular")

    # Create an identity matrix
    identity = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        identity[i][i] = Fraction(1)

    # Augment the matrix with the identity matrix
    augmented = [row + identity[i] for i, row in enumerate(m)]

    # Perform row operations to reduce to identity matrix
    for i in range(n):
        pivot = augmented[i][i]
        if pivot == Fraction(0):
            # Swap rows to find a non-zero pivot
            for j in range(i + 1, n):
                if augmented[j][i] != Fraction(0):
                    augmented[i], augmented[j] = augmented[j], augmented[i]
                    pivot = augmented[i][i]
                    break
            if pivot == Fraction(0):
                raise SingularMatrix("Matrix is singular")
        # Normalize the pivot row
        factor = augmented[i][i] 
        for j in range(i, n):
            augmented[i][j] = augmented[i][j] / factor
        # Eliminate all other rows in the column
        for j in range(n):
            if j != i and augmented[j][i] != Fraction(0):
                factor = augmented[j][i]
                for k in range(i, n):
                    augmented[j][k] = augmented[j][k] - factor * augmented[i][k]

    # Extract the inverse matrix
    inverse_matrix = [[augmented[i][j] for j in range(n)] for i in range(n)]
    return inverse_matrix

def solve(a: List[List[Fraction]], b: List[Fraction]) -> List[Fraction]:
    """Solve the linear system a·x = b."""
    if not isinstance(a, list):
        raise ShapeError("Input must be a list of lists")
    if not a:
        raise ShapeError("Matrix a is empty")
    n = len(a)
    if not all(len(row) == n for row in a):
        raise ShapeError("Matrix a must have consistent row lengths")
    if len(b) != n:
        raise ShapeError("Vector b must have length n")

    # Check if matrix a is singular
    det = det(a)
    if det == Fraction(0):
        raise SingularMatrix("Matrix a is singular")

    # Create the inverse of a
    a_inv = inverse(a)

    # Compute x = a_inv * b
    x = [Fraction(0) for _ in range(n)]
    for i in range(n):
        for j in range(n):
            x[i] += a_inv[i][j] * b[j]
    return x

def matmul(a: List[List[Fraction]], b: List[List[Fraction]]) -> List[List[Fraction]]:
    """Compute the matrix product."""
    if not isinstance(a, list):
        raise ShapeError("Input must be a list of lists")
    if not a:
        raise ShapeError("Matrix a is empty")
    if not isinstance(b, list):
        raise ShapeError("Input must be a list of lists")
    if not b:
        raise ShapeError("Matrix b is empty")
    n = len(a)
    if not all(len(row) == n for row in a):
        raise ShapeError("Matrix a must have consistent row lengths")
    m = len(b[0])
    if not all(len(row) == m for row in b):
        raise ShapeError("Matrix b must have consistent column lengths")

    # Check if the number of columns of a matches the number of rows of b
    if len(a[-1]) != m:
        raise ShapeError("Number of columns of a does not match number of rows of b")

    # Create the result matrix
    result = [[Fraction(0) for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            for k in range(len(a[i])):
                result[i][j] += a[i][k] * b[k][j]

    return result

def identity(n: int) -> List[List[Fraction]]:
    """Create an n×n identity matrix."""
    if not isinstance(n, int):
        raise ShapeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be at least 1")

    matrix = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        matrix[i][i] = Fraction(1)
    return matrix
