from typing import Dict, List, Optional

class Autocomplete:
    def __init__(self):
        self.trie: Dict[str, Dict[str, float]] = {}
        self.words: Dict[str, Dict[str, float]] = {}
        self._casefold_key = str.casefold

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("Cannot add empty word")

        # Convert to casefolded form for comparison
        key = self._casefold_key(word)

        # Check if the key already exists
        if key in self.trie:
            # Update the stored word and weight
            self.trie[key][word] = weight
            self.words[key][word] = weight
        else:
            self.trie[key] = {word: weight}
            self.words[key] = {word: weight}

    def complete(self, prefix: str, k: int = 10) -> List[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        # Convert prefix to casefolded form
        prefix_key = self._casefold_key(prefix)

        results = []
        for word_key in self.trie:
            if self._casefold_key(word_key).startswith(prefix_key):
                # Get the word and weight
                word = self.words[word_key].get(word_key, "")
                weight = self.trie[word_key][word]
                if word:
                    results.append((weight, word))

        # Sort by weight descending, then by word (casefolded)
        results.sort(key=lambda x: (-x[0], x[1]))

        # Take top k results
        return [word for weight, word in results[:k]]

    def delete(self, word: str) -> bool:
        key = self._casefold_key(word)

        if key in self.trie:
            # Check if the word exists in the trie
            if word in self.trie[key]:
                # Remove the word from the trie and words dict
                del self.trie[key][word]
                del self.words[key][word]
                return True
        return False

    def __len__(self) -> int:
        return len(self.words)

    def __contains__(self, word: str) -> bool:
        key = self._casefold_key(word)
        return key in self.words
