def parse(text: str) -> List[List[int]]:
    """
    Parses a string into a 9x9 Sudoku grid.

    Args:
        text: A string containing 81 characters (digits 1-9, 0, or .).

    Returns:
        A list of lists representing the Sudoku grid.

    Raises:
        ValueError: If the input is not 81 characters, or contains invalid characters.
    """
    if not text.strip():
        raise ValueError("Input string is empty")

    # Remove all whitespace characters
    cleaned_text = re.sub(r'[ \t\r\n\v\f]', '', text)

    # Check if the cleaned text has exactly 81 characters
    if len(cleaned_text) != 81:
        raise ValueError("Invalid number of cells")

    # Convert to a grid of integers
    grid = []
    for i in range(9):
        row = []
        for j in range(9):
            c = cleaned_text[i * 9 + j]
            if c in '123456789':
                row.append(int(c))
            else:
                row.append(0)
        grid.append(row)

    return grid

