"""
A Python module for reading, checking, and solving standard 9×9 Sudoku puzzles.
With hints and difficulty rating support.
"""

from typing import List, Tuple, Optional, Dict
import re

def parse(text: str) -> List[List[int]]:
    """
    Parses a string into a 9x9 Sudoku grid.

    Args:
        text: A string containing 81 characters (digits 1-9, 0, or .).

    Returns:
        A list of lists representing the Sudoku grid.

    Raises:
        ValueError: If the input is not 81 characters, or contains invalid characters.
    """
    if not text.strip():
        raise ValueError("Input string is empty")

    # Remove all whitespace characters
    cleaned_text = re.sub(r'[ \t\r\n\v\f]', '', text)

    # Check if the cleaned text has exactly 81 characters
    if len(cleaned_text) != 81:
        raise ValueError("Invalid number of cells")

    # Convert to a grid of integers
    grid = []
    for i in range(9):
        row = []
        for j in range(9):
            c = cleaned_text[i * 9 + j]
            if c in '123456789':
                row.append(int(c))
            else:
                row.append(0)
        grid.append(row)

    return grid

def to_string(grid: List[List[int]]) -> str:
    """
    Converts a 9x9 Sudoku grid into a string representation.

    Args:
        grid: A list of lists representing the Sudoku grid.

    Returns:
        A string with 81 characters, representing the Sudoku grid.

    Raises:
        ValueError: If the grid is not 9x9.
    """
    if not all(len(row) == 9 for row in grid):
        raise ValueError("Grid must be 9x9")

    result = []
    for row in grid:
        line = ''.join(str(cell) if cell != 0 else '.' for cell in row)
        result.append(line)

    return ''.join(result)

def is_valid(grid: List[List[int]]) -> bool:
    """
    Checks if a Sudoku grid is valid.

    Args:
        grid: A 9x9 grid of integers (0-9).

    Returns:
        True if the grid is valid, False otherwise.
    """
    # Check rows
    for row in grid:
        seen = set()
        for num in row:
            if num != 0 and num in seen:
                return False
            seen.add(num)

    # Check columns
    for col in range(9):
        seen = set()
        for row in range(9):
            num = grid[row][col]
            if num != 0 and num in seen:
                return False
            seen.add(num)

    # Check 3x3 boxes
    for box in range(3):
        for row in range(3):
            seen = set()
            for col in range(3):
                num = grid[row + 3 * box][col + 3 * box]
                if num != 0 and num in seen:
                    return False
                seen.add(num)

    return True

def solve(grid: List[List[int]]) -> List[List[int]] | None:
    """
    Solves a Sudoku puzzle and returns a new valid grid, or None if no solution exists.

    Args:
        grid: A 9x9 grid of integers (0-9).

    Returns:
        A new valid 9x9 grid if a solution exists, otherwise None.
    """
    # Make a deep copy to avoid modifying the original grid
    new_grid = [row.copy() for row in grid]

    # Solve the puzzle using backtracking
    def backtrack():
        for row in range(9):
            for col in range(9):
                if new_grid[row][col] == 0:
                    for num in range(1, 10):
                        if is_valid_row_col_box(new_grid, row, col, num):
                            new_grid[row][col] = num
                            if backtrack():
                                return True
                            new_grid[row][col] = 0
                    return False
        return True

    if backtrack():
        return new_grid
    else:
        return None

