# search.py

def first_index(a, x):
    """Returns the index of the first element equal to x in a sorted list, or -1 if not found."""
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            high = mid - 1  # Continue searching left for possible earlier occurrence
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return low if a[low] == x else -1

def last_index(a, x):
    """Returns the index of the last element equal to x in a sorted list, or -1 if not found."""
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            low = mid + 1  # Continue searching right for possible later occurrence
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return high if a[high] == x else -1

def insertion_point(a, x):
    """Returns the smallest index i such that inserting x before a[i] keeps a sorted."""
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            high = mid - 1  # Continue searching left for possible earlier occurrence
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return low if a[low] > x else len(a)

def count(a, x):
    """Returns the number of elements equal to x in a sorted list."""
    low = 0
    high = len(a) - 1
    count = 0
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            count += 1
            high = mid - 1
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return count

def search_rotated(a, x):
    """Finds the index of x in a rotated sorted list with distinct elements."""
    if not a:
        return -1

    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return -1

def rotation_offset(a):
    """Returns the rotation offset of a rotated sorted list, or raises ValueError if empty."""
    if not a:
        raise ValueError("Cannot compute rotation offset for an empty list.")

    # Find the index of the smallest element
    low = 0
    high = len(a) - 1
    while low < high:
        mid = (low + high) // 2
        if a[mid] < a[low]:
            low = mid + 1
        elif a[mid] > a[high]:
            high = mid
        else:
            low = mid + 1
    return low

def isqrt(n):
    """Returns the largest integer r with r*r <= n, exact for arbitrarily large integers."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer.")
    if n < 0:
        raise ValueError("n must be non-negative.")
    if n == 0:
        return 0
    low = 0
    high = n
    while low < high:
        mid = (low + high) // 2
        if mid * mid > n:
            high = mid
        else:
            low = mid + 1
    return low
