def placeholders(template: str) -> List[str]:
    """Returns the placeholder names in order of first appearance, each once."""
    placeholders = []
    # Regular expression to find placeholders
    pattern = r'{(?P<name>[a-zA-Z_][a-zA-Z0-9_]*):?(?P<default>.*)}'
    matches = re.finditer(pattern, template)

    for match in matches:
        name = match.group('name')
        if name:
            placeholders.append(name)
    return placeholders

def render(template: str, values: Mapping[str, object]) -> str:
    """Replaces each placeholder with `str(values[name])` if `name` is in `values` (even when the value is an empty string or `None`), else with its default."""
    placeholders = placeholders(template)
    result = []
    i = 0
    while i < len(template):
        if template[i] == '{':
            # Check for a valid placeholder
            if i + 1 >= len(template):
                raise TemplateError(i, "Missing closing } for placeholder")
            if template[i + 1] != '}'':
                raise TemplateError(i, f"Invalid placeholder start at {i}")

            # Parse the placeholder
            name_part = ''
            default_part = ''
            i += 2
            while i < len(template) and template[i] != '}':
                if template[i] == '{':
                    # Nested placeholder, but we are not handling it here
                    raise TemplateError(i, "Nested placeholder not supported")
                if template[i].isalnum() or template[i] == '_':
                    name_part += template[i]
                elif template[i] == ':':
                    # Split into name and default
                    default_part = ''
                    i += 1
                    while i < len(template) and template[i] != '}':
                        if template[i] == ':':
                            default_part += template[i]
                            i += 1
                            while i < len(template) and template[i] != '}':
                                default_part += template[i]
                                i += 1
                            break
                        else:
                            default_part += template[i]
                            i += 1
                    break
                else:
                    break
            if not name_part:
                raise TemplateError(i, "Invalid placeholder name")

            # Check for default
            if i < len(template) and template[i] == ':':
                i += 1
                default_part = ''
                while i < len(template) and template[i] != '}':
                    if template[i] == ':':
                        default_part += template[i]
                        i += 1
                        while i < len(template) and template[i] != '}':
                            default_part += template[i]
                            i += 1
                        break
                    else:
                        default_part += template[i]
                        i += 1
                i += 1  # Skip the closing }
            else:
                default_part = ''

            # Check for missing name
            if name_part not in values:
                if default_part:
                    result.append(default_part)
                else:
                    result.append(str(values.get(name_part, "")))
            else:
                result.append(str(values[name_part]))
            i += 1  # Skip the closing }
        else:
            result.append(template[i])
            i += 1

    return ''.join(result)
