# todo/store.py
from typing import Dict, Any, List, Set, Optional
import json
from pathlib import Path
import os
import re
from dataclasses import dataclass
from enum import Enum
from typing import Callable, Union, cast
from .model import Task, StoreError, Status, Tag

@dataclass
class TodoStore:
    path: Path

    def __init__(self, path: str):
        self.path = Path(path)
        self._load()

    def _load(self) -> None:
        try:
            with self.path.open("r") as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError):
            self._create_empty()
        self._store = data

    def _create_empty(self) -> None:
        self._store = {
            "version": 1,
            "next_id": 1,
            "tasks": []
        }

    def _save(self) -> None:
        with self.path.open("w") as f:
            json.dump(self._store, f, indent=2)

    def add(self, title: str, tags: tuple = ()) -> Task:
        if not title:
            raise ValueError("Title cannot be empty")
        normalized_title = self.normalize_title(title)
        normalized_tags = [self.normalize_tag(tag) for tag in tags]
        normalized_tags = list(set(normalized_tags))
        normalized_tags.sort()

        task_id = self._store["next_id"]
        self._store["next_id"] += 1
        task = Task(task_id, normalized_title, normalized_tags)
        self._store["tasks"].append(task.to_dict())
        self._save()
        return task

    def get(self, task_id: int) -> Task:
        if task_id < 1:
            raise ValueError("Task ID must be positive")
        if task_id > len(self._store["tasks"]):
            raise KeyError(f"Task with ID {task_id} not found")
        return Task.from_dict(self._store["tasks"][task_id - 1])

    def list(self, status: str = "open", tags: tuple = ()) -> List[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError("Invalid status")
        filtered_tasks = []
        if status == "open":
            filtered_tasks = [task for task in self._store["tasks"] if task["done"] is False]
        elif status == "done":
            filtered_tasks = [task for task in self._store["tasks"] if task["done"] is True]
        else:  # "all"
            filtered_tasks = self._store["tasks"]

        # Apply tags filter
        filtered = []
        for task in filtered_tasks:
            task_tags = task["tags"]
            if all(tag in [tag.lower() for tag in tags] for tag in task_tags):
                filtered.append(task)

        # Sort by id
        filtered.sort(key=lambda x: x["id"])
        return [Task.from_dict(task) for task in filtered]

    def mark_done(self, task_id: int) -> Task:
        if task_id < 1:
            raise ValueError("Task ID must be positive")
        if task_id > len(self._store["tasks"]):
            raise KeyError(f"Task with ID {task_id} not found")
        task = self._store["tasks"][task_id - 1]
        task["done"] = True
        self._store["tasks"][task_id - 1] = task
        self._save()
        return Task.from_dict(task)

    def remove(self, task_id: int) -> Task:
        if task_id < 1:
            raise ValueError("Task ID must be positive")
        if task_id > len(self._store["tasks"]):
            raise KeyError(f"Task with ID {task_id} not found")
        task = self._store["tasks"][task_id - 1]
        del self._store["tasks"][task_id - 1]
        self._save()
        return Task.from_dict(task)

    def edit(self, task_id: int, title: Optional[str] = None, add_tags: tuple = (), remove_tags: tuple = ()) -> Task:
        if task_id < 1:
            raise ValueError("Task ID must be positive")
        if task_id > len(self._store["tasks"]):
            raise KeyError(f"Task with ID {task_id} not found")
        task = self._store["tasks"][task_id - 1]
        original_title = task["title"]

        if title is not None:
            normalized_title = self.normalize_title(title)
            if normalized_title != original_title:
                task["title"] = normalized_title

        # Add tags
        for tag in add_tags:
            if tag not in task["tags"]:
                task["tags"].append(tag)
        task["tags"].sort()

        # Remove tags
        for tag in remove_tags:
            if tag in task["tags"]:
                task["tags"].remove(tag)

        self._store["tasks"][task_id - 1] = task
        self._save()
        return Task.from_dict(task)

    def _validate_task(self, task: Dict[str, Any]) -> None:
        if "id" not in task or not isinstance(task["id"], int):
            raise ValueError("Task ID must be an integer")
        if "title" not in task or not isinstance(task["title"], str):
            raise ValueError("Task title must be a string")
        if "tags" not in task or not isinstance(task["tags"], list):
            raise ValueError("Task tags must be a list of strings")
        if "done" not in task or not isinstance(task["done"], bool):
            raise ValueError("Task done must be a boolean")

        # Validate title
        if not self.normalize_title(task["title"]):
            raise ValueError("Invalid title")

        # Validate tags
        for tag in task["tags"]:
            if not self.normalize_tag(tag):
                raise ValueError("Invalid tag")

    def _validate_store(self) -> None:
        if "version" not in self._store or self._store["version"] != 1:
            raise StoreError("Invalid store format")
        if "next_id" not in self._store or not isinstance(self._store["next_id"], int):
            raise StoreError("Invalid store format")
        if not isinstance(self._store["tasks"], list):
            raise StoreError("Invalid store format")
        for task in self._store["tasks"]:
            self._validate_task(task)

    def _create_store(self) -> None:
        self._store = {
            "version": 1,
            "next_id": 1,
            "tasks": []
        }
        self._save()
