    parser.add_argument("--file", help="The path to the todo file", default="todo.json")
    subparsers = parser.add_subparsers(dest="command")

    # Add command
    add_parser = subparsers.add_parser("add")
    add_parser.add_argument("TITLE", help="The title of the task")
    add_parser.add_argument("--tag", nargs="+", help="Tags to add (e.g., --tag home --tag shop)")

    # List command
    list_parser = subparsers.add_parser("list")
    list_parser.add_argument("--status", choices=["open", "done", "all"], default="open")
    list_parser.add_argument("--tag", nargs="+", help="Tags to filter by")

    # Done command
    done_parser = subparsers.add_parser("done")
    done_parser.add_argument("ID", help="The task ID to mark as done")

    # Remove command
    remove_parser = subparsers.add_parser("remove")
    remove_parser.add_argument("ID", help="The task ID to remove")

    # Edit command
    edit_parser = subparsers.add_parser("edit")
    edit_parser.add_argument("ID", help="The task ID to edit")
    edit_parser.add_argument("--title", help="The new title")
    edit_parser.add_argument("--tag", nargs="+", help="Tags to add")
    edit_parser.add_argument("--untag", nargs="+", help="Tags to remove")

    args = parser.parse_args(argv)

    # Set up the store
    store_path = Path(args.file)
    try:
        store = TodoStore(store_path)
    except StoreError as e:
        print(f"error: {e}")
        return 3

    if args.command == "add":
        # Add a task
        title = args.TITLE
        tags = []
        if add_parser._args:
            tags = add_parser._args["--tag"]
        task = store.add(title, tags)
        print(f"added {task.id}")
        return 0

    elif args.command == "list":
        # List tasks
        status = args.status
        tags = []
        if list_parser._args:
            tags = list_parser._args["--tag"]
        tasks = store.list(status, tags)
        for task in tasks:
            status_str = " [x]" if task.done else " [ ]"
            tags_str = " #{}".format(tag) for tag in task.tags
            print(f"{task.id} {status_str} {task.title}{tags_str}")

        return 0

    elif args.command == "done":
        # Mark tasks as done
        for id in args.ID:
