    elif args.command == "remove":
        # Remove a task
        try:
            id = int(args.ID)
        except ValueError:
            print(f"error: {args.ID} is not a valid integer")
            return 2
        task = store.get(id)
        store.remove(id)
        print(f"removed {id}")
        return 0

    elif args.command == "edit":
        # Edit a task
        try:
            id = int(args.ID)
        except ValueError:
            print(f"error: {args.ID} is not a valid integer")
