        if task["due"] is not None and not isinstance(task["due"], date):
            task["due"] = None

        # Validate title
        if not self.normalize_title(task["title"]):
            raise ValueError("Invalid title")

        # Validate tags
        for tag in task["tags"]:
            if not self.normalize_tag(tag):
                raise ValueError("Invalid tag")

    def _validate_store(self) -> None:
        if "version" not in self._store or self._store["version"] != 2:
            raise StoreError("Invalid store format")
        if "next_id" not in self._store or not isinstance(self._store["next_id"], int):
            raise StoreError("Invalid store format")
        if not isinstance(self._store["tasks"], list):
            raise StoreError("Invalid store format")
        for task in self._store["tasks"]:
            self._validate_task(task)

    def _create_store(self) -> None:
        self._store = {
            "version": 2,
            "next_id": 1,
            "tasks": []
        }
        self._save()
