# todo/cli.py
import argparse
import json
from datetime import date
from pathlib import Path
from typing import List, Dict, Any, Optional
from .model import Task, StoreError
from .store import TodoStore

def main(argv: List[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="A small command-line todo manager with priorities, due dates, and sorting")
    parser.add_argument("--file", help="The path to the todo file", default="todo.json")
    subparsers = parser.add_subparsers(dest="command")

    # Add command
    add_parser = subparsers.add_parser("add")
    add_parser.add_argument("TITLE", help="The title of the task")
    add_parser.add_argument("--priority", choices=[Priority.high.value, Priority.normal.value, Priority.low.value], help="Priority of the task")
    add_parser.add_argument("--due", help="Due date of the task (YYYY-MM-DD)")
    add_parser.add_argument("--tag", nargs="+", help="Tags to add (e.g., --tag home --tag shop)")

    # List command
    list_parser = subparsers.add_parser("list")
    list_parser.add_argument("--status", choices=["open", "done", "all"], default="open")
    list_parser.add_argument("--tag", nargs="+", help="Tags to filter by")
    list_parser.add_argument("--overdue", action="store_true", help="Only list tasks with due date before today")
    list_parser.add_argument("--today", help="Today's date (YYYY-MM-DD)")
    list_parser.add_argument("--sort", choices=["id", "priority", "due"], default="id")

    # Done command
    done_parser = subparsers.add_parser("done")
    done_parser.add_argument("ID", help="The task ID to mark as done")

    # Remove command
    remove_parser = subparsers.add_parser("remove")
    remove_parser.add_argument("ID", help="The task ID to remove")

    # Edit command
    edit_parser = subparsers.add_parser("edit")
    edit_parser.add_argument("ID", help="The task ID to edit")
    edit_parser.add_argument("--title", help="The new title")
    edit_parser.add_argument("--priority", choices=[Priority.high.value, Priority.normal.value, Priority.low.value], help="New priority")
    edit_parser.add_argument("--due", help="New due date (YYYY-MM-DD)")
    edit_parser.add_argument("--no-due", action="store_true", help="Remove due date")
    edit_parser.add_argument("--tag", nargs="+", help="Tags to add")
    edit_parser.add_argument("--untag", nargs="+", help="Tags to remove")

    args = parser.parse_args(argv)

    # Set up the store
    store_path = Path(args.file)
    try:
        store = TodoStore(store_path)
    except StoreError as e:
        print(f"error: {e}")
        return 3

    if args.command == "add":
        # Add a task
        title = args.TITLE
        priority = None
        due = None
        tags = []
        if add_parser._args:
            tags = add_parser._args["--tag"]
            if add_parser._args["--priority"]:
                priority = add_parser._args["--priority"]
            if add_parser._args["--due"]:
                due = add_parser._args["--due"]

        task = store.add(title, tags, priority, due)
        print(f"added {task.id}")
        return 0

    elif args.command == "list":
        # List tasks
        status = args.status
        tags = []
        if list_parser._args:
            tags = list_parser._args["--tag"]
        overdue = args.overdue
        today = None
        sort = args.sort

        if list_parser._args and args.today:
            today = date.fromisoformat(args.today)

        tasks = store.list(status, tags, overdue, today, sort)
        for task in tasks:
            status_str = " [x]" if task.done else " [ ]"
            priority_str = " !{}".format(task.priority) if task.priority != "normal" else ""
            due_str = " due:{}".format(task.due.strftime("%Y-%m-%d")) if task.due else ""
            tags_str = " #{}".format(tag) for tag in task.tags
            print(f"{task.id} {status_str} {task.title}{priority_str}{due_str}{tags_str}")

        return 0

    elif args.command == "done":
        # Mark tasks as done
        for id in args.ID:
            try:
                id = int(id)
            except ValueError:
                print(f"error: {id} is not a valid integer")
                return 2
            task = store.get(id)
            store.mark_done(id)
            print(f"done {id}")
        return 0

    elif args.command == "remove":
        # Remove a task
        try:
            id = int(args.ID)
        except ValueError:
            print(f"error: {args.ID} is not a valid integer")
            return 2
        task = store.get(id)
        store.remove(id)
        print(f"removed {id}")
        return 0

    elif args.command == "edit":
        # Edit a task
        try:
            id = int(args.ID)
        except ValueError:
            print(f"error: {args.ID} is not a valid integer")
            return 2
        task = store.get(id)
        if not task:
            print(f"error: no task with id {id}")
            return 1
        if not args.title:
            # No title provided, do not change title
            pass
        else:
            title = args.title
            normalized_title = store.normalize_title(title)
            if normalized_title != task.title:
                task.title = normalized_title

        # Add tags
        for tag in args.tag:
            if tag not in task.tags:
                task.tags.append(tag)
        task.tags.sort()

        # Remove tags
        for tag in args.untag:
            if tag in task.tags:
                task.tags.remove(tag)

        # Update priority and due date
        if args.priority:
            task.priority = args.priority
        if args.no_due:
            task.due = None
        if args.due:
            try:
                task.due = date.fromisoformat(args.due)
            except ValueError:
                print(f"error: {args.due} is not a valid date")
                return 2

        store.edit(id, title, args.tag, args.untag, args.priority, args.due, args.no_due)
        print(f"edited {id}")
        return 0

    else:
        print("error: unknown command")
        return 2

if __name__ == "__main__":
    sys.exit(main())
