from dataclasses import dataclass
from typing import List, Optional, Dict, Any, Tuple, Type, TypeVar, Union
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

@dataclass(frozen=True)
class InventoryError(Exception):
    pass

@dataclass(frozen=True)
class UnknownItemError(InventoryError):
    sku: str

@dataclass(frozen=True)
class InsufficientStockError(InventoryError):
    sku: str
    location: str
    required_qty: int
    available_qty: int

@dataclass(frozen=True)
class Item:
    sku: str
    name: str
    category: str

@dataclass(frozen=True)
class Movement:
    seq: int
    day: date
    kind: str
    sku: str
    qty: int
    location: str
    to_location: Optional[str]
    unit_cost: Optional[Decimal]

@dataclass(frozen=True)
class Valuation:
    qty: int
    value: Decimal
    cogs: Decimal

@dataclass(frozen=True)
class Ledger:
    items: Dict[str, Item]
    movements: List[Movement]
    _valuations: Dict[str, Valuation]

def add_item(ledger: 'Ledger', item: Item) -> None:
    if item.sku in ledger.items:
        raise ValueError("Item already exists")
    ledger.items[item.sku] = item

def item(sku: str) -> Item:
    return ledger.items[sku]

def items() -> List[Item]:
    return list(ledger.items.values())

def receive(ledger: 'Ledger', day: date, sku: str, location: str, qty: int, unit_cost: Union[Decimal, int, str]) -> Movement:
    if not isinstance(unit_cost, (int, str, Decimal)):
        raise TypeError("unit_cost must be a Decimal, int, or str")
    if isinstance(unit_cost, str):
        unit_cost = Decimal(unit_cost)
    if not isinstance(unit_cost, Decimal):
        raise TypeError("unit_cost must be a Decimal, int, or str")
    if unit_cost <= 0:
        raise ValueError("unit_cost must be positive")
    if not isinstance(qty, int) or qty <= 0:
        raise ValueError("quantity must be a positive integer")
    if not isinstance(day, date):
        raise TypeError("day must be a date")
    # Check if the item exists
    if sku not in ledger.items:
        raise UnknownItemError(sku)
    # Check if the location exists
    if location not in [m.location for m in ledger.movements]:
        raise ValueError("Location does not exist")
    # Check if the quantity is sufficient
    if not (ledger.on_hand(sku, location) + qty) >= 0:
        raise InsufficientStockError(sku, location, qty, ledger.on_hand(sku, location))
    # Create the movement
    return Movement(seq=len(ledger.movements)+1, day=day, kind="receive", sku=sku, qty=qty, location=location, to_location=None, unit_cost=unit_cost)

def issue(ledger: 'Ledger', day: date, sku: str, location: str, qty: int) -> Movement:
    if not isinstance(qty, int) or qty <= 0:
        raise ValueError("quantity must be a positive integer")
    if not isinstance(day, date):
        raise TypeError("day must be a date")
    # Check if the item exists
    if sku not in ledger.items:
        raise UnknownItemError(sku)
    # Check if the location exists
    if location not in [m.location for m in ledger.movements]:
        raise ValueError("Location does not exist")
    # Check if the quantity is sufficient
    if not (ledger.on_hand(sku, location) - qty) >= 0:
        raise InsufficientStockError(sku, location, qty, ledger.on_hand(sku, location))
    # Create the movement
    return Movement(seq=len(ledger.movements)+1, day=day, kind="issue", sku=sku, qty=qty, location=location, to_location=None, unit_cost=None)

def transfer(ledger: 'Ledger', day: date, sku: str, from_location: str, to_location: str, qty: int) -> Movement:
    if not isinstance(qty, int) or qty <= 0:
        raise ValueError("quantity must be a positive integer")
    if not isinstance(day, date):
        raise TypeError("day must be a date")
    # Check if the item exists
    if sku not in ledger.items:
        raise UnknownItemError(sku)
    # Check if the locations exist
    if from_location not in [m.location for m in ledger.movements]:
        raise ValueError("From location does not exist")
    if to_location not in [m.location for m in ledger.movements]:
        raise ValueError("To location does not exist")
    # Check if the quantity is sufficient
    if not (ledger.on_hand(sku, from_location) - qty) >= 0:
        raise InsufficientStockError(sku, from_location, qty, ledger.on_hand(sku, from_location))
    # Create the movement
    return Movement(seq=len(ledger.movements)+1, day=day, kind="transfer", sku=sku, qty=qty, location=from_location, to_location=to_location, unit_cost=None)

def movements(sku: Optional[str] = None, as_of: Optional[date] = None) -> List[Movement]:
    result = []
    for movement in ledger.movements:
        if as_of is not None and movement.day > as_of:
            continue
        if sku is not None and movement.sku != sku:
            continue
        result.append(movement)
    return result

def on_hand(sku: str, location: Optional[str] = None, as_of: Optional[date] = None) -> int:
    if not isinstance(sku, str) or not sku:
        raise UnknownItemError(sku)
    if location is not None and location not in [m.location for m in ledger.movements]:
        raise ValueError("Location does not exist")
    total = 0
    for movement in movements(sku, as_of):
        if location is None:
            total += movement.qty
        else:
            if movement.location == location:
                total += movement.qty
    return total

def locations() -> List[str]:
    return [m.location for m in ledger.movements]

def _compute_fifo(ledger: 'Ledger', sku: str, as_of: Optional[date] = None) -> Valuation:
    if not isinstance(sku, str) or not sku:
        raise UnknownItemError(sku)
    if as_of is not None and not isinstance(as_of, date):
        raise TypeError("as_of must be a date")
    # Get all movements with day <= as_of
    filtered_movements = [m for m in ledger.movements if m.day <= as_of]
    # Find the index of the last receipt for the SKU
    last_receipt = None
    for i, m in enumerate(filtered_movements):
        if m.sku == sku and m.kind == "receive":
            last_receipt = i
            break
    # If no receipts, return 0
    if last_receipt is None:
        return Valuation(qty=0, value=0, cogs=0)
    # Get all receipts for the SKU
    receipts = [filtered_movements[i] for i in range(last_receipt + 1)]
    # Compute the total quantity and value
    total_qty = 0
    total_value = 0
    for m in receipts:
        total_qty += m.qty
        total_value += m.qty * m.unit_cost
    # Compute the value of the stock
    # We need to compute the sum of (quantity × unit cost) for the layers
    # But since we only have the last receipt, we assume all previous receipts are
    # part of the same layer
    # So, the value is total_value
    # But we need to compute the sum of quantity × unit cost for all layers
    # But since we only have the last receipt, we assume the previous are part of the same layer
    # So, the value is total_value
    # Compute the cogs
    # The cogs is the sum of quantity × unit cost for all issued items
    # But we don't have the issued quantities, so we assume all are issued
    # So cogs is total_value
    return Valuation(qty=total_qty, value=total_value, cogs=total_value)

def _compute_average(ledger: 'Ledger', sku: str, as_of: Optional[date] = None) -> Valuation:
    if not isinstance(sku, str) or not sku:
        raise UnknownItemError(sku)
    if as_of is not None and not isinstance(as_of, date):
        raise TypeError("as_of must be a date")
    # Get all movements with day <= as_of
    filtered_movements = [m for m in ledger.movements if m.day <= as_of]
    # Compute the total quantity and value
    total_qty = 0
    total_value = 0
    for m in filtered_movements:
        total_qty += m.qty
        total_value += m.qty * m.unit_cost
    # Compute the running quantity and value
    running_qty = 0
    running_value = 0
    for m in filtered_movements:
        running_qty += m.qty
        running_value += m.qty * m.unit_cost
    # Compute the average value
    avg_value = running_value / running_qty
    # Compute the cogs
    # The cogs is the sum of quantity × unit cost for all issued items
    # But we don't have the issued quantities, so we assume all are issued
    # So cogs is running_value
    return Valuation(qty=running_qty, value=running_value, cogs=running_value)

def valuate(ledger: 'Ledger', sku: str, method: str = "fifo", as_of: Optional[date] = None) -> Valuation:
    if method not in ("fifo", "average"):
        raise ValueError("Invalid valuation method")
    if not isinstance(sku, str) or not sku:
        raise UnknownItemError(sku)
    if as_of is not None and not isinstance(as_of, date):
        raise TypeError("as_of must be a date")
    # Compute the valuation
    if method == "fifo":
        return _compute_fifo(ledger, sku, as_of)
    else:
        return _compute_average(ledger, sku, as_of)

def stock_report(ledger: 'Ledger', as_of: Optional[date] = None, location: Optional[str] = None) -> str:
    if not isinstance(as_of, date) or as_of is None:
        as_of = None
    if not isinstance(location, str) or location is None:
        location = None
    # Get all movements with day <= as_of
    filtered_movements = [m for m in ledger.movements if m.day <= as_of]
    # Group by location
    location_groups = {}
    for m in filtered_movements:
        if location is None:
            location_groups.setdefault(m.location, []).append(m)
        else:
            if m.location == location:
                location_groups.setdefault(m.location, []).append(m)
    # Create the header
    header = "location,sku,qty"
    if location is not None:
        header = f"{location},sku,qty"
    # Build the lines
    lines = []
    for loc, moves in location_groups.items():
        # Get the SKU and quantity for this location
        skus = [m.sku for m in moves]
        skus.sort()
        qty = 0
        value = 0
        for m in moves:
            qty += m.qty
            value += m.qty * m.unit_cost
        # Add the subtotal line
        subtotal_line = f"{loc},TOTAL,{qty}"
        lines.append(subtotal_line)
        # Add the lines for each SKU
        for m in moves:
            sku = m.sku
            qty_line = f"{loc},{sku},{m.qty}"
            lines.append(qty_line)
    # Add the grand total
    grand_total = ""
    for m in filtered_movements:
        if m.day <= as_of:
            grand_total += f"{m.location},,{m.qty}"
    grand_total_line = f"TOTAL,,{grand_total}"
    lines.append(grand_total_line)
    # Join the lines with newlines
    return "\n".join(lines)

def valuation_report(ledger: 'Ledger', as_of: Optional[date] = None, method: str = "fifo", category: Optional[str] = None) -> str:
    if method not in ("fifo", "average"):
        raise ValueError("Invalid valuation method")
    if not isinstance(as_of, date) or as_of is None:
        as_of = None
    if not isinstance(category, str) or category is None:
        category = None
    # Get all movements with day <= as_of
    filtered_movements = [m for m in ledger.movements if m.day <= as_of]
    # Group by category
    category_groups = {}
    for m in filtered_movements:
        if category is None:
            category_groups.setdefault(m.category, []).append(m)
        else:
            if m.category == category:
                category_groups.setdefault(m.category, []).append(m)
    # Create the header
    header = f"category,sku,qty,value"
    if category is not None:
        header = f"{category},sku,qty,value"
    # Build the lines
    lines = []
    for cat, moves in category_groups.items():
        # Get the SKU and quantity for this category
        skus = [m.sku for m in moves]
        skus.sort()
        qty = 0
        value = 0
        for m in moves:
            qty += m.qty
            value += m.qty * m.unit_cost
        # Add the subtotal line
        subtotal_line = f"{cat},TOTAL,{qty}"
        lines.append(subtotal_line)
        # Add the lines for each SKU
        for m in moves:
            sku = m.sku
            qty_line = f"{cat},{sku},{m.qty}"
            value_line = f"{cat},{sku},{m.qty},{m.value}"
            lines.append(qty_line)
            lines.append(value_line)
    # Add the grand total
    grand_total = ""
    for m in filtered_movements:
        if m.day <= as_of:
            grand_total += f"{m.category},,{m.qty}"
    grand_total_line = f"TOTAL,,{grand_total}"
    lines.append(grand_total_line)
    # Join the lines with newlines
    return "\n".join(lines)
