class TemplateError(Exception):
    pass

class TemplateSyntaxError(TemplateError):
    pass

class TemplateRenderError(TemplateError):
    pass

class Token(NamedTuple):
    kind: str
    value: str
    lineno: int

def tokenize(source: str) -> List[Token]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i] in ' \n':
            i += 1
        elif source[i] in '({%#':
            # Start of a tag
            i += 1
            tag = source[i]
            if tag == '{':
                # Handle tag with no closing delimiter
                if i + 1 >= len(source) or source[i+1] != '}':
                    tokens.append(Token('block', source[i:i+1], i))
                    i += 1
                else:
                    # Handle tag with closing delimiter
                    end = source.find('}', i)
                    if end == -1:
                        tokens.append(Token('block', source[i:i+1], i))
                        i += 1
                    else:
                        content = source[i:end]
                        tokens.append(Token('block', content, i))
                        i = end + 1
            elif tag == '%':
                # Handle tag with no closing delimiter
                if i + 1 >= len(source) or source[i+1] != '}':
                    tokens.append(Token('block', source[i:i+1], i))
                    i += 1
                else:
                    # Handle tag with closing delimiter
                    end = source.find('}', i)
                    if end == -1:
                        tokens.append(Token('block', source[i:i+1], i))
                        i += 1
                    else:
                        content = source[i:end]
                        tokens.append(Token('block', content, i))
                        i = end + 1
            elif tag == '#':
                # Handle tag with no closing delimiter
                if i + 1 >= len(source) or source[i+1] != '}':
                    tokens.append(Token('block', source[i:i+1], i))
                    i += 1
                else:
                    # Handle tag with closing delimiter
                    end = source.find('}', i)
                    if end == -1:
                        tokens.append(Token('block', source[i:i+1], i))
                        i += 1
                    else:
                        content = source[i:end]
                        tokens.append(Token('block', content, i))
                        i = end + 1
            else:
                # Unknown tag
                tokens.append(Token('block', source[i:i+1], i))
                i += 1
        else:
            # Regular text
            if i + 1 < len(source) and source[i+1] == ' ':
                # Skip whitespace
                i += 2
            else:
                # Extract atom or filter
                if i + 1 < len(source) and source[i+1] in '[]':
                    # Handle variable reference
                    i += 2
                    atom = source[i:i+1]
                    tokens.append(Token('var', atom, i))
                    i += 1
                else:
                    # Extract atom
                    atom = source[i:i+1]
                    tokens.append(Token('var', atom, i))
                    i += 1
    return tokens
