from typing import List, Tuple, Dict
import re

def parse_blocks(text: str) -> List[Tuple]:
    blocks = []
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        if lines[i].strip() == '':
            i += 1
            continue
        # Check for fenced code block
        if lines[i].startswith('```'):
            i += 1
            lang = ''
            while i < len(lines) and lines[i].startswith('```'):
                lang = lines[i].split('```')[1].split(' ')[0] if i < len(lines) else ''
                i += 1
            code_lines = []
            while i < len(lines) and lines[i].startswith('```'):
                code_lines.append(lines[i].split('```')[1])
                i += 1
            code = ''.join(code_lines)
            blocks.append(('code', lang, code))
        # Check for heading
        elif lines[i].startswith('#'):
            text_part = lines[i].strip('# ')
            while i < len(lines) and lines[i].startswith('#'):
                i += 1
            text_part = text_part.strip()
            # Remove final # if it's the whole text or preceded by whitespace
            if i < len(lines) and lines[i].strip() == '':
                i += 1
            text_part = text_part.strip()
            if i < len(lines) and lines[i].strip() == '':
                i += 1
            blocks.append(('heading', i - 1, text_part))
        # Check for horizontal rule
        elif all(c in '-*_' for c in lines[i]):
            blocks.append(('hr',))
        # Check for blockquote
        elif lines[i].startswith('>'):
            i += 1
            children = []
            while i < len(lines) and lines[i].startswith('>'):
                children.append(parse_blocks(lines[i]))
                i += 1
            blocks.append(('blockquote', children))
        # Check for list
        elif lines[i].startswith('-') or lines[i].startswith('*') or lines[i].startswith('+'):
            i += 1
            ordered = False
            start = None
            items = []
            while i < len(lines) and (lines[i].startswith('-') or lines[i].startswith('*') or lines[i].startswith('+') or lines[i].startswith('1') or lines[i].startswith('2') or lines[i].startswith('3') or lines[i].startswith('4') or lines[i].startswith('5') or lines[i].startswith('6') or lines[i].startswith('7') or lines[i].startswith('8') or lines[i].startswith('9')):
                item = lines[i].strip()
                if lines[i].startswith('-') or lines[i].startswith('*') or lines[i].startswith('+'):
                    ordered = False
                    start = None
                    items.append(item)
                else:
                    # Check for ordered list
                    if lines[i].startswith('1') or lines[i].startswith('2') or lines[i].startswith('3') or lines[i].startswith('4') or lines[i].startswith('5') or lines[i].startswith('6') or lines[i].startswith('7') or lines[i].startswith('8') or lines[i].startswith('9'):
                        ordered = True
                        start = int(lines[i].split(' ')[1])
                        items.append(item)
                    else:
                        # Bullet list
                        ordered = False
                        items.append(item)
                i += 1
            blocks.append(('list', ordered, start, items))
        # Check for table
        elif lines[i].startswith('|'):
            # Check if it's a table start
            if i < len(lines) and not lines[i].strip() == '':
                # Check if it's a table start
                if not lines[i].strip().startswith(' '):
                    # Check for delimiter row
                    delimiter_row = None
                    j = i + 1
                    while j < len(lines) and lines[j].strip() == '':
                        j += 1
                    if j < len(lines) and lines[j].strip() != '':
                        # Check if delimiter row matches
                        cells = lines[j].strip().split('|')
                        if len(cells) == 0:
                            continue
                        # Check if delimiter row matches
                        if all(c in '-*:' for c in cells[0]) and len(cells) == 3:
                            delimiter_row = True
                        elif all(c in '-*:' for c in cells[0]) and len(cells) == 2:
                            delimiter_row = True
                        elif all(c in '-*:' for c in cells[0]) and len(cells) == 1:
                            delimiter_row = True
