# fsm/machine.py
from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict, Any, TypeVar, Type
from typing import Generic, TypeVar, Dict, List, Union
from enum import Enum
import warnings

class MachineError(Exception):
    pass

class InvalidTransition(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition for event '{event}' in state '{state}'")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"Guard rejected for event '{event}' in state '{state}'")
        self.state = state
        self.event = event

@dataclass(frozen=True)
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None

@dataclass(frozen=True)
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str], str]
    target: Union[str, None]
    guard: Optional[Callable] = None
    action: Optional[Callable] = None

@dataclass(frozen=True)
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any]

class Machine(Generic[Event]):
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Optional[Dict] = None):
        if not states:
            raise ValueError("States list cannot be empty")

        self.states = []
        self.transitions = []
        self.initial = initial
        self.context = context or {}

        # Validate states
        for state in states:
            if isinstance(state, str):
                self.states.append(State(state, on_enter=None, on_exit=None))
            else:
                self.states.append(state)

        # Validate transitions
        for transition in transitions:
            source = transition.source
            target = transition.target
            if not isinstance(source, (str, list, tuple)):
                raise ValueError(f"Invalid source for transition: {source}")
            if not isinstance(target, (str, None)):
                raise ValueError(f"Invalid target for transition: {target}")

            if source == '*' and target == '*':
                raise ValueError("Invalid source and target for transition: both must be '*' or a state")

            if source not in self.states:
                raise ValueError(f"Source state '{source}' not found")
            if target not in self.states and target is not None:
                raise ValueError(f"Target state '{target}' not found")

            self.transitions.append(transition)

        self.state = initial
        self.history = []
        self._listeners = []
        self._event_data = {}

    def can_fire(self, event: str, **data: dict) -> bool:
        # Check if any transition matches the current state and event
        candidates = []
        for transition in self.transitions:
            if transition.event == event and self._is_match(transition.source, self.state):
                candidates.append(transition)

        if not candidates:
            return False

        # Check guards
        for candidate in candidates:
            if candidate.guard is not None:
                if not candidate.guard(self, event, data):
                    continue
            if candidate.target is not None:
                if candidate.target == self.state:
                    # Internal transition, no on_exit or on_enter
                    pass
                else:
                    # Normal transition
                    if candidate.guard is not None:
                        if not candidate.guard(self, event, data):
                            continue
            else:
                # Internal transition
                pass

        return True

    def fire(self, event: str, **data: dict) -> str:
        # Find candidates
        candidates = []
        for transition in self.transitions:
            if transition.event == event and self._is_match(transition.source, self.state):
                candidates.append(transition)

        if not candidates:
            raise InvalidTransition(self.state, event)

        # Use the same data for all events in this call
        event_data = data.copy()

        # Check guards
        for candidate in candidates:
            if candidate.guard is not None:
                if not candidate.guard(self, event, event_data):
                    continue
            if candidate.target is not None:
                if candidate.target == self.state:
                    # Internal transition, no on_exit or on_enter
                    pass
                else:
                    # Normal transition
                    if candidate.guard is not None:
                        if not candidate.guard(self, event, event_data):
                            continue
            else:
                # Internal transition
                pass

        # Process the first candidate
        for candidate in candidates:
            if candidate.guard is not None:
                if not candidate.guard(self, event, event_data):
                    continue
            if candidate.target is not None:
                if candidate.target == self.state:
                    # Internal transition, no on_exit or on_enter
                    pass
                else:
                    # Normal transition
                    if candidate.guard is not None:
                        if not candidate.guard(self, event, event_data):
                            continue
            else:
                # Internal transition
                pass

            # Run on_exit and on_enter
            if candidate.target is not None:
                if candidate.target != self.state:
                    # Normal transition
                    if candidate.on_exit is not None:
                        candidate.on_exit(self, event, event_data)
                    if candidate.action is not None:
                        candidate.action(self, event, event_data)
                    if candidate.on_enter is not None:
                        candidate.on_enter(self, event, event_data)
                    self.state = candidate.target
                    self.history.insert(0, (self.state, event, candidate.target))
                    if candidate.on_transition is not None:
                        for listener in self._listeners:
                            listener(self.state, event, candidate.target)
            else:
                # Internal transition
                if candidate.on_exit is not None:
                    candidate.on_exit(self, event, event_data)
                if candidate.action is not None:
                    candidate.action(self, event, event_data)
                if candidate.on_enter is not None:
                    candidate.on_enter(self, event, event_data)
                self.history.insert(0, (self.state, event, self.state))
                if candidate.on_transition is not None:
                    for listener in self._listeners:
                        listener(self.state, event, self.state)

            return self.state

        raise GuardRejected(self.state, event)

    def _is_match(self, source: Union[str, List[str], Tuple[str]], current_state: str) -> bool:
        if isinstance(source, str):
            return source == current_state
        elif isinstance(source, list):
            return any(s == current_state for s in source)
        elif isinstance(source, tuple):
            return any(s == current_state for s in source)
        else:
            return source == '*'  # Match any state

    def available_events(self) -> List[str]:
        events = set()
        for transition in self.transitions:
            events.add(transition.event)
        return sorted(events)

    def on_transition(self, listener: Callable):
        self._listeners.append(listener)

    def reset(self):
        self.state = self.initial
        self.history = []
        self._listeners = []
        self._event_data = {}

    def __str__(self):
        return f"Machine(state={self.state}, history={self.history})"
