# vending.py
from typing import Dict, List, Optional, Tuple, Any
from fsm import Machine, State, Transition, Event, MachineError, InvalidTransition, GuardRejected
import warnings

class VendingMachine:
    def __init__(self, products: Dict[str, Tuple[int, int]]):
        self.products = products
        self.machine = self._build_machine()
        self.credit = 0
        self.stock = {}
        self.sales = {}
        self.revenue = 0

    def _build_machine(self) -> Machine:
        # Initialize states and transitions
        states = []
        for code, (price, stock) in self.products.items():
            states.append(State(code, on_enter=self._on_enter, on_exit=self._on_exit))
            self.stock[code] = stock
            self.sales[code] = 0
            self.revenue += price * stock

        # Transitions
        transitions = []
        # Insert
        transitions.append(Transition("insert", "*", "credit", guard=self._insert_guard, action=self._insert_action))
        # Select
        transitions.append(Transition("select", "credit", "*", guard=self._select_guard, action=self._select_action))
        # Cancel
        transitions.append(Transition("cancel", "credit", "*", guard=self._cancel_guard, action=self._cancel_action))
        # Service
        transitions.append(Transition("service", "*", "maintenance", guard=self._service_guard, action=self._service_action))
        # Restock
        transitions.append(Transition("restock", "maintenance", "*", guard=self._restock_guard, action=self._restock_action))

        # Machine initialization
        initial_state = "idle"
        return Machine(states, transitions, initial_state)

    def _on_enter(self, machine: Machine, event: Event):
        if event.name == "insert":
            self.credit += event.data["value"]
        elif event.name == "select":
            price, stock = self.products[event.source]
            if self.credit < price:
                raise InsufficientCredit(self.credit, price)
            change = self.credit - price
            self.credit = 0
            self.sales[event.source] += 1
            self.revenue += price
            self.stock[event.source] -= 1
            if self.stock[event.source] == 0:
                self.sales[event.source] = 0
                self.revenue -= price
            if self.sales[event.source] > 0:
                self.revenue -= change
            self._update_revenue()
            self._update_sales()
            self._update_stock()
            return
        elif event.name == "cancel":
            self.credit = 0
            self._update_revenue()
            self._update_sales()
            self._update_stock()
            return

    def _on_exit(self, machine: Machine, event: Event):
        if event.name == "insert":
            self._update_revenue()
        elif event.name == "select":
            self._update_sales()
            self._update_stock()
        elif event.name == "cancel":
            self._update_stock()
        elif event.name == "service":
            self._update_stock()
        elif event.name == "restock":
            self._update_stock()

    def _insert_guard(self, machine: Machine, event: Event, data: dict) -> bool:
        value = data["value"]
        if value not in (5, 10, 25, 100):
            return False
        return True

    def _insert_action(self, machine: Machine, event: Event, data: dict):
        value = data["value"]
        self.credit += value

    def _select_guard(self, machine: Machine, event: Event, data: dict) -> bool:
        code = event.source
        if code not in self.products:
            return False
        price, stock = self.products[code]
        if stock <= 0:
            return False
        if self.credit < price:
            return False
        return True

    def _select_action(self, machine: Machine, event: Event, data: dict):
        code = event.source
        price, stock = self.products[code]
        change = self.credit - price
        self.credit = 0
        self.sales[code] += 1
        self.revenue += price
        self.stock[code] -= 1
        if self.stock[code] == 0:
            self.sales[code] = 0
            self.revenue -= price
        if self.sales[code] > 0:
            self.revenue -= change
        self._update_revenue()
        self._update_sales()
        self._update_stock()
        return change

    def _cancel_guard(self, machine: Machine, event: Event, data: dict) -> bool:
        return True

    def _cancel_action(self, machine: Machine, event: Event, data: dict):
        self.credit = 0
        self._update_revenue()
        self._update_sales()
        self._update_stock()
        return self.credit

    def _service_guard(self, machine: Machine, event: Event, data: dict) -> bool:
        return True

    def _service_action(self, machine: Machine, event: Event, data: dict):
        self.state = "maintenance"
        return None

    def _restock_guard(self, machine: Machine, event: Event, data: dict) -> bool:
        code = event.source
        if code not in self.products:
            return False
        price = data["price"]
        if price is None:
            return False
        return True

    def _restock_action(self, machine: Machine, event: Event, data: dict):
        code = event.source
        qty = data["qty"]
        price = data["price"]
        self.stock[code] += qty
        if self.stock[code] > self.products[code][1]:
            self.stock[code] = self.products[code][1]
        return None

    def _update_revenue(self):
        self.revenue = 0
        for code, (price, stock) in self.products.items():
            if self.stock[code] > 0:
                self.revenue += price * self.stock[code]

    def _update_sales(self):
        self.sales = {}
        for code, (price, stock) in self.products.items():
            if self.stock[code] > 0:
                self.sales[code] = 0
                self.revenue += price * self.stock[code]
                self.sales[code] += 1

    def _update_stock(self):
        self.stock = {}
        for code, (price, stock) in self.products.items():
            self.stock[code] = stock

    def insert(self, coin: int) -> int:
        if self.state != "idle" and self.state != "credit":
            raise InvalidTransition(self.state, "insert")

        if coin not in (5, 10, 25, 100):
            raise ValueError("Invalid coin")

        try:
            self.credit += coin
        except Exception as e:
            raise MachineError(f"Error adding coin: {e}")

        self.state = "credit"
        return self.credit

    def select(self, code: str) -> List[int]:
        if self.state != "credit":
            raise InvalidTransition(self.state, "select")

        if code not in self.products:
            raise ValueError("Unknown code")

        price, stock = self.products[code]
        if stock <= 0:
            raise SoldOut("Stock is out of the product")

        if self.credit < price:
            raise InsufficientCredit(self.credit, price)

        change = self.credit - price
        self.credit = 0
        self.sales[code] += 1
        self.revenue += price
        self.stock[code] -= 1
        if self.stock[code] == 0:
            self.sales[code] = 0
            self.revenue -= price
        if self.sales[code] > 0:
            self.revenue -= change

        self._update_revenue()
        self._update_sales()
        self._update_stock()

        return [price, change]

    def cancel(self) -> List[int]:
        if self.state != "credit":
            raise InvalidTransition(self.state, "cancel")

        if self.credit == 0:
            raise MachineError("No credit to cancel")

        self.credit = 0
        self._update_revenue()
        self._update_sales()
        self._update_stock()

        return [self.credit]

    def service(self) -> None:
        if self.state != "idle":
            raise InvalidTransition(self.state, "service")

        self.state = "maintenance"
        return None

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        if self.state != "maintenance":
            raise InvalidTransition(self.state, "restock")

        if qty < 1:
            raise ValueError("Quantity must be at least 1")

        if price is None:
            if code not in self.products:
                raise ValueError("Product not found")
            price = self.products[code][0]

        self.stock[code] += qty
        if self.stock[code] > self.products[code][1]:
            self.stock[code] = self.products[code][1]
        return None

    def resume(self) -> None:
        if self.state != "maintenance":
            raise InvalidTransition(self.state, "resume")

        self.state = "idle"
        return None
