    pass

class Chart:
    def __init__(self):
        self.accounts: Dict[str, Account] = {}
        self.root_accounts: List[Account] = []
        self._depth_map: Dict[str, int] = {}

    def add(self, code: str, name: str, type_: AccountType, parent: Optional[str] = None) -> Account:
        if not code:
            raise ValueError("Code cannot be empty")
        if code in self.accounts:
            raise ValueError(f"Account with code '{code}' already exists")
        if parent and parent not in self.accounts:
            raise ValueError(f"Parent account '{parent}' does not exist")
        if type_ not in (AccountType.asset, AccountType.liability, AccountType.equity, AccountType.income, AccountType.expense):
            raise ValueError(f"Invalid account type: {type_}")

        depth = self._depth_map.get(parent, 0) + 1
        self._depth_map[code] = depth
        self.accounts[code] = Account(code, name, type_, parent)
        self.root_accounts.append(self.accounts[code])
        return self.accounts[code]

    def get(self, code: str) -> Account:
        if code not in self.accounts:
            raise KeyError(f"Account with code '{code}' does not exist")
        return self.accounts[code]

    def children(self, code: str) -> List[Account]:
        return [self.accounts[child_code] for child_code in sorted(self.accounts.keys()) if self.accounts[child_code].parent == code]

    def roots(self) -> List[Account]:
        return sorted(self.root_accounts, key=lambda acc: acc.code)

    def is_leaf(self, code: str) -> bool:
        return len(self.children(code)) == 0

    def walk(self) -> List[Tuple[Account, int]]:
        result = []
        for account in self.root_accounts:
            result.append((account, 0))
            for child in self.children(account.code):
                result.append((child, 0))
        return result

    def balance(self, code: str, start: Optional[date] = None, end: Optional[date] = None) -> Decimal:
        if code not in self.accounts:
            raise KeyError(f"Account with code '{code}' does not exist")
        if start is not None and end is not None:
            if start > end:
                raise ValueError("start > end")
        balance = Decimal(0)
        for account, depth in self.walk():
            if start is not None and end is not None:
                if start > account.day or end < account.day:
                    continue
            if account.code == code:
                balance += account.debit - account.credit
                continue
            for child in self.children(account.code):
                balance += child.debit - child.credit
        return balance

    def ledger(self, code: str) -> List[LedgerRow]:
        result = []
        for account, depth in self.walk():
            if account.code == code:
                for line in account.lines:
                    result.append(LedgerRow(account.number, line.day, line.memo, line.debit, line.credit, line.balance))
                continue
            for child in self.children(account.code):
                for row in child.ledger(account.code):
                    result.append(row)
        return result

    def __str__(self):
        return "Chart"
