from typing import List, Tuple, Optional, Dict
from decimal import Decimal
from datetime import date
from dataclasses import dataclass
from enum import Enum
from collections import namedtuple

@dataclass(frozen=True)
class UnbalancedEntryError(ValueError):
    pass

@dataclass(frozen=True)
class Line:
    account: str
    debit: Decimal
    credit: Decimal

@dataclass(frozen=True)
class Entry:
    number: int
    day: date
    memo: str
    lines: Tuple[Line, ...]

@dataclass(frozen=True)
class LedgerRow:
    number: int
    day: date
    memo: str
    debit: Decimal
    credit: Decimal
    balance: Decimal

class Journal:
    def __init__(self, chart: 'Chart'):
        self.chart = chart
        self.entries: List[Entry] = []
        self.entry_number = 1

    def post(self, day: date, memo: str, lines: Tuple[Line, ...]) -> Entry:
        if len(lines) < 2:
            raise ValueError("Must have at least two lines")

        for line in lines:
            if line.account not in self.chart.accounts:
                raise KeyError(f"Line account '{line.account}' does not exist")
            if self.chart.is_leaf(line.account):
                if line.debit == 0 and line.credit == 0:
                    raise ValueError("Line must have non-zero amount")
            else:
                if line.debit == 0 or line.credit == 0:
                    raise ValueError("Line must have non-zero amount")

        if sum(line.debit for line in lines) != sum(line.credit for line in lines):
            raise UnbalancedEntryError("Debits and credits are not equal")

        entry = Entry(
            number=self.entry_number,
            day=day,
            memo=memo,
            lines=lines
        )
        self.entries.append(entry)
        self.entry_number += 1
        return entry

    def entries(self) -> List[Entry]:
        return self.entries

    def balance(self, code: str, start: Optional[date] = None, end: Optional[date] = None) -> Decimal:
        if code not in self.chart.accounts:
            raise KeyError(f"Account with code '{code}' does not exist")
        if start is not None and end is not None:
            if start > end:
                raise ValueError("start > end")
        balance = Decimal(0)
        for entry in self.entries:
            for line in entry.lines:
                if start is not None and end is not None:
                    if start > line.day or end < line.day:
                        continue
                balance += line.debit - line.credit
        return balance

    def ledger(self, code: str) -> List[LedgerRow]:
        result = []
        for entry in self.entries:
            for line in entry.lines:
                if line.account == code:
                    result.append(LedgerRow(
                        entry.number,
                        line.day,
                        line.memo,
                        line.debit,
                        line.credit,
                        line.balance
                    ))
        return result
