from typing import List, Tuple, Optional
from decimal import Decimal
from datetime import date
from dataclasses import dataclass
from enum import Enum
from collections import namedtuple

@dataclass(frozen=True)
class TrialBalanceLine:
    account: str
    balance: Decimal

@dataclass(frozen=True)
class IncomeStatementLine:
    line_type: str
    account: str
    balance: Decimal

class Statement:
    def __init__(self, chart: 'Chart'):
        self.chart = chart

    def trial_balance(self, as_of: Optional[date] = None) -> str:
        period = "all entries" if as_of is None else f"entries with day <= {as_of}"
        period_str = f"as of {as_of.strftime('%Y-%m-%d')} " if as_of else "all entries"
        period_str += f" ({period})"

        lines = []
        lines.append(f"TRIAL BALANCE {period_str}")

        accounts = self.chart.walk()
        for account, depth in accounts:
            balance = self.balance(account.code, None, None)
            lines.append(f"{' ' * (depth * 2)}{account.code} {account.name}: {balance:.2f}")

        total_debits = Decimal(0)
        total Credits = Decimal(0)
        for account, depth in accounts:
            if account.type in (AccountType.asset, AccountType.equity):
                total_debits += self.balance(account.code, None, None)
            elif account.type in (AccountType.liability, AccountType.expense):
                total Credits += self.balance(account.code, None, None)

        lines.append(f"Total debits: {total_debits:.2f}")
        lines.append(f"Total credits: {total Credits:.2f}")

        return "\n".join(lines)

    def income_statement(self, start: date, end: date) -> str:
        if start > end:
            raise ValueError("start > end")

        lines = []
        lines.append(f"INCOME STATEMENT {start.strftime('%Y-%m-%d')} to {end.strftime('%Y-%m-%d')}")

        income_accounts = [account for account, depth in self.chart.walk() if account.type == AccountType.income]
        for account in income_accounts:
            balance = self.balance(account.code, start, end)
            lines.append(f"{' ' * (depth * 2)}{account.code} {account.name}: {balance:.2f}")

        total_income = Decimal(0)
        for account in income_accounts:
            total_income += self.balance(account.code, start, end)

        lines.append(f"Total income: {total_income:.2f}")

        expense_accounts = [account for account, depth in self.chart.walk() if account.type == AccountType.expense]
        for account in expense_accounts:
            balance = self.balance(account.code, start, end)
            lines.append(f"{' ' * (depth * 2)}{account.code} {account.name}: {balance:.2f}")

        total_expense = Decimal(0)
        for account in expense_accounts:
            total_expense += self.balance(account.code, start, end)

        lines.append(f"Total expenses: {total_expense:.2f}")

        net_income = total_income - total_expense
        lines.append(f"Net income: {net_income:.2f}")

        return "\n".join(lines)
