# library/__init__.py
from typing import Optional, List, Dict, Any, Callable
from dataclasses import dataclass
from datetime import date

# Re-export the necessary classes and functions
from library.catalog import Catalog, Book, Member
from library.loans import Loan, LoanError
from library.fines import Policy
from library.fines import HOLD_PICKUP_DAYS
from library.fines import due_date, fine_for
from library.fines import Policy, POLICY

@dataclass
class Library:
    catalog: Catalog
    clock: Callable[[], date]

    def available(self, isbn: str) -> int:
        # Calculate available copies
        available = self.catalog.copies(isbn) - self.catalog.active_loans(isbn) - self.catalog.ready_holds(isbn)
        return available

    def checkout(self, member_id: str, isbn: str) -> Loan:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        # Check if isbn exists
        isbn_info = self.catalog.book(isbn)
        if not isbn_info:
            raise KeyError("ISBN not found")

        # Check if member has a loan on this isbn
        existing_loan = self.catalog.active_loans(isbn)
        if existing_loan > 0:
            raise LoanError("Duplicate loan")

        # Check if member has a ready hold on this isbn
        ready_hold = self.catalog.ready_holds(isbn)
        if ready_hold > 0:
            # Use the set-aside copy
            return self._process_renewal(member_id, isbn, existing_loan, ready_hold)

        # Check if member has a fine balance
        if self._check_fine(member_id):
            raise LoanError("Blocked")

        # Check if member has max_loans
        if self.catalog.active_loans(isbn) >= self.catalog.max_loans(member_id):
            raise LoanError("Limit reached")

        # Check availability
        if self.available(isbn) <= 0:
            raise LoanError("Not available")

        # Create loan
        loan_id = self._generate_loan_id()
        due_date_obj = due_date(self.clock(), self.catalog.loan_days(member_id))
        loan = Loan(
            loan_id,
            member_id,
            isbn,
            self.clock(),
            due_date_obj,
            renewals=0,
            returned=None,
            fine=0
        )

        # Update catalog
        self.catalog.update_loan(loan)

        # Update member
        self.catalog.update_member(member_id, {"loans": self.catalog.active_loans(isbn) + 1})

        return loan

    def _process_renewal(self, member_id: str, isbn: str, existing_loan: int, ready_hold: int) -> Loan:
        # Check if there is a ready hold
        if ready_hold > 0:
            # Remove the ready hold and set the copy aside
            self.catalog.update_ready_hold(isbn, ready_hold - 1)
            return self._create_loan(member_id, isbn, existing_loan + 1)

        # If no ready hold, check if there is an existing loan
        if existing_loan > 0:
            # Renew the loan
            new_due_date = due_date(self.clock(), self.catalog.loan_days(member_id))
            return self._create_loan(member_id, isbn, existing_loan + 1, new_due_date)

        return self._create_loan(member_id, isbn, 1)

    def _create_loan(self, member_id: str, isbn: str, loan_count: int, new_due_date: Optional[date] = None) -> Loan:
        # Create new loan
        loan_id = self._generate_loan_id()
        due_date_obj = new_due_date or due_date(self.clock(), self.catalog.loan_days(member_id))
        loan = Loan(
            loan_id,
            member_id,
            isbn,
            self.clock(),
            due_date_obj,
            renewals=0,
            returned=None,
            fine=0
        )

        # Update catalog
        self.catalog.update_loan(loan)

        # Update member
        self.catalog.update_member(member_id, {"loans": self.catalog.active_loans(isbn) + loan_count})

        return loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        # Check if isbn exists
        isbn_info = self.catalog.book(isbn)
        if not isbn_info:
            raise KeyError("ISBN not found")

        # Check if there is already a loan or hold
        if self.catalog.active_loans(isbn) > 0 or self.catalog.ready_holds(isbn) > 0:
            raise LoanError("Not available")

        # Check if there is a hold
        if self.catalog.holds(isbn):
            raise LoanError("Duplicate loan")

        # Add hold
        position = self.catalog.holds(isbn) + 1
        self.catalog.update_hold(isbn, position)
        return position

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        # Check if isbn exists
        isbn_info = self.catalog.book(isbn)
        if not isbn_info:
            raise KeyError("ISBN not found")

        # Check if there is a hold
        hold = self.catalog.hold(isbn, member_id)
        if not hold:
            raise KeyError("Hold not found")

        # Cancel the hold
        self.catalog.update_hold(isbn, hold.position - 1)
        self.catalog.update_ready_hold(isbn, hold.position - 1)

    def holds(self, isbn: str) -> List[str]:
        # Get the list of member ids in the queue
        holds = self.catalog.holds(isbn)
        return [member_id for member_id in holds]

    def hold_status(self, member_id: str, isbn: str) -> str:
        # Check if there is a hold
        hold = self.catalog.hold(isbn, member_id)
        if not hold:
            raise KeyError("Hold not found")

        # Determine status
        if hold.status == "ready":
            return f"('ready', {hold.deadline})"
        else:
            return f"('waiting', {hold.position})"

    def renew(self, loan_id: int) -> date:
        # Check if loan exists
        loan = self.catalog.loan(loan_id)
        if not loan:
            raise KeyError("Loan not found")

        # Check if loan is overdue
        if loan.returned is not None and loan.returned > self.clock():
            raise LoanError("Overdue")

        # Check if there is a hold
        if self.catalog.ready_holds(loan.isbn) > 0:
            raise LoanError("Isbn has a hold")

        # Check if there is any hold
        if self.catalog.holds(loan.isbn):
            raise LoanError("Isbn has a hold")

        # Check if there is a loan
        if self.catalog.active_loans(loan.isbn) >= self.catalog.max_loans(loan.member_id):
            raise LoanError("Limit reached")

        # Create new due date
        new_due_date = due_date(self.clock(), self.catalog.loan_days(loan.member_id))

        # Update loan
        new_loan = Loan(
            loan_id,
            loan.member_id,
            loan.isbn,
            self.clock(),
            new_due_date,
            renewals=loan.renewals + 1,
            returned=loan.returned,
            fine=loan.fine
        )

        # Update catalog
        self.catalog.update_loan(new_loan)

        # Update member
        self.catalog.update_member(loan.member_id, {"loans": self.catalog.active_loans(loan.isbn) + 1})

        return new_due_date

    def checkin(self, loan_id: int) -> int:
        # Check if loan exists
        loan = self.catalog.loan(loan_id)
        if not loan:
            raise KeyError("Loan not found")

        # Check if loan is already returned
        if loan.returned is not None:
            raise LoanError("Already returned")

        # Calculate fine
        late_days = (loan.returned - loan.due).days
        fine = fine_for(loan.member_id, loan.due, loan.returned)
        loan.fine = fine

        # Update loan
        new_loan = Loan(
            loan_id,
            loan.member_id,
            loan.isbn,
            loan.start,
            loan.due,
            loan.renewals,
            loan.returned,
            fine
        )

        # Update catalog
        self.catalog.update_loan(new_loan)

        # Update member
        self.catalog.update_member(loan.member_id, {"loans": self.catalog.active_loans(loan.isbn) - 1, "balance": self.catalog.balance(loan.member_id) + fine})

        # Set copy aside for a waiting hold
        if self.catalog.ready_holds(loan.isbn) > 0:
            self.catalog.update_ready_hold(loan.isbn, self.catalog.ready_holds(loan.isbn) - 1)

        # Return fine
        return fine

    def accrued_fine(self, loan_id: int) -> int:
        # Check if loan exists
        loan = self.catalog.loan(loan_id)
        if not loan:
            raise KeyError("Loan not found")

        # Check if loan is already returned
        if loan.returned is not None:
            return loan.fine

        # Calculate fine
        late_days = (loan.returned - loan.due).days
        fine = fine_for(loan.member_id, loan.due, loan.returned)
        return fine

    def balance(self, member_id: str) -> int:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        return member.balance

    def pay(self, member_id: str, amount: int) -> int:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        # Check if amount is valid
        if amount <= 0:
            raise ValueError("Amount must be positive")

        # Check if amount is within balance
        if member.balance < amount:
            raise ValueError("Amount exceeds balance")

        # Update balance
        new_balance = member.balance - amount
        self.catalog.update_member(member_id, {"balance": new_balance})

        return new_balance

    def loans(self, member_id: str) -> List[Loan]:
        # Check if member exists
        member = self.catalog.member(member_id)
        if not member:
            raise KeyError("Member not found")

        # Get active loans
        active_loans = self.catalog.active_loans(member_id)
        return [loan for loan in self.catalog.loans(member_id) if loan.returned is None and loan.due > self.clock()]

    def overdue(self) -> List[Loan]:
        # Get active loans that are overdue
        overdue_loans = [loan for loan in self.loans() if loan.returned is None and loan.due < self.clock()]
        return overdue_loans

    def _generate_loan_id(self) -> int:
        # Generate a new loan ID
        return len(self.catalog.loans()) + 1
