    balance: Dict[str, int]

    def __init__(self):
        self.books = {}
        self.members = {}
        self.loans = {}
        self.holds = {}
        self.active_loans = {}
        self.ready_holds = {}
        self.balance = {}

    def add_book(self, isbn: str, title: str, author: str, copies: int = 1) -> Book:
        if isbn in self.books:
            raise ValueError("Book with this ISBN already exists")
        if copies < 1:
            raise ValueError("Copies must be at least 1")
        self.books[isbn] = Book(isbn, title, author, copies)
        return self.books[isbn]

    def add_copies(self, isbn: str, n: int) -> int:
        if isbn not in self.books:
            raise KeyError("ISBN not found")
        if n < 1:
            raise ValueError("Number of copies must be at least 1")
        self.books[isbn].copies += n
        return self.books[isbn].copies

    def add_member(self, member_id: str, name: str, kind: str = 'standard') -> Member:
        if member_id in self.members:
            raise ValueError("Member with this ID already exists")
        if kind not in POLICY:
            raise ValueError("Invalid member kind")
        self.members[member_id] = Member(member_id, name, kind)
        return self.members[member_id]

    def book(self, isbn: str) -> Book:
        if isbn not in self.books:
            raise KeyError("Book not found")
        return self.books[isbn]

    def member(self, member_id: str) -> Member:
        if member_id not in self.members:
            raise KeyError("Member not found")
        return self.members[member_id]

    def search(self, text: str) -> List[Book]:
        results = []
        for isbn, book in self.books.items():
            if text.lower() in book.title.lower() or text.lower() in book.author.lower():
                results.append(book)
        return results

    def update_loan(self, loan: Loan):
        self.loans[loan.loan_id] = loan

    def update_member(self, member_id: str, updates: Dict[str, Any]):
        if member_id not in self.members:
            raise KeyError("Member not found")
        for key, value in updates.items():
            if key == "loans":
                self.members[member_id]["loans"] = value
            elif key == "balance":
                self.members[member_id]["balance"] = value
            elif key == "active_loans":
                self.members[member_id]["active_loans"] = value
            elif key == "ready_holds":
                self.members[member_id]["ready_holds"] = value
            elif key == "holds":
                self.members[member_id]["holds"] = value
            elif key == "name":
                self.members[member_id]["name"] = value
            elif key == "kind":
                self.members[member_id]["kind"] = value
            else:
                raise KeyError(f"Unknown update key: {key}")

    def update_hold(self, isbn: str, position: int):
        if isbn not in self.holds:
            self.holds[isbn] = []
        self.holds[isbn].insert(position - 1, self.holds[isbn][position - 1])
        self.holds[isbn].pop(position)

    def update_ready_hold(self, isbn: str, position: int):
        if isbn not in self.ready_holds:
            self.ready_holds[isbn] = 0
        self.ready_holds[isbn] += position

    def holds(self, isbn: str) -> List[str]:
        if isbn not in self.holds:
            return []
        return self.holds[isbn]

    def hold(self, isbn: str, member_id: str) -> Optional[Dict]:
        if isbn not in self.holds:
            return None
        if member_id not in self.holds[isbn]:
            return None
        position = self.holds[isbn].index(member_id) + 1
        return {"status": "ready", "deadline": self.holds[isbn][position - 1], "position": position}

    def _check_fine(self, member_id: str) -> bool:
        if member_id not in self.members:
            return True
        return self.members[member_id]["balance"] > 0

    def active_loans(self, isbn: str) -> int:
        return self.active_loans.get(isbn, 0)

    def ready_holds(self, isbn: str) -> int:
        return self.ready_holds.get(isbn, 0)

    def loans(self, member_id: str) -> List[Loan]:
        if member_id not in self.members:
            return []
        return [loan for loan in self.loans.values() if loan.member_id == member_id]

    def overdue(self) -> List[Loan]:
        return [loan for loan in self.loans.values() if loan.returned is None and loan.due < self.clock()]
