# web/request.py
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple, Union
from .headers import Headers
from .http_error import HTTPError, BadRequest, NotFound, MethodNotAllowed
from .response import Response

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, List[str]]
    state: Dict[str, Any]

    def __post_init__(self):
        self.query = self._parse_query()
        self.content_type = self._parse_content_type()
        self.text = self._parse_text()
        self.json = self._parse_json()

    def _parse_query(self) -> Dict[str, List[str]]:
        query = {}
        parts = self.query_string.split('&')
        for part in parts:
            if not part:
                continue
            name, value = part.split('=', 1)
            name = name.strip()
            value = value.strip()
            if '=' in value:
                name, value = value.split('=', 1)
                value = value.strip()
            query[name] = query.get(name, [])
            query[name].append(value)
        return query

    def _parse_content_type(self) -> Tuple[str, Dict[str, str]]:
        content_type = self.headers.get('Content-Type', '')
        if not content_type:
            return ('', {})
        parts = content_type.split(';')
        media_type = parts[0].strip().lower()
        params = {}
        for part in parts[1:]:
            if not part:
                continue
            name, value = part.split('=', 1)
            name = name.strip().lower()
            value = value.strip()
            if name:
                params[name] = value
        return (media_type, params)

    def _parse_text(self) -> str:
        if not self.body:
            return ''
        charset = self.headers.get('Content-Type', 'text/plain').split(';', 1)[1].strip().lower()
        try:
            return self.body.decode(charset or 'utf-8')
        except UnicodeError:
            raise BadRequest("Invalid UTF-8 in text")

    def _parse_json(self) -> Dict[str, Any]:
        if not self.body:
            return {}
        try:
            return eval(self.body.decode('utf-8'))
        except Exception as e:
            raise BadRequest("Invalid JSON") from e

    def text(self, s: str, status: int = 200) -> Response:
        return Response(status=status, text=s)

    def json(self, obj: Any, status: int = 200) -> Response:
        return Response(status=status, json=obj)

    def to_bytes(self) -> bytes:
        status_line = f"HTTP/1.1 {self.status} {self.reason}"
        headers = []
        for name, value in self.headers.items():
            headers.append(f"{name.lower()}: {value}")
        headers.append(f"Content-Length: {len(self.body)}")
        return b"\r\n".join([status_line] + headers + [b'']) + self.body
