# web/router.py
from typing import Tuple, Dict, List, Optional
from .request import Request, parse_request
from .http_error import HTTPError, NotFound, MethodNotAllowed
from .middleware import App

class Router:
    def __init__(self):
        self.routes = []
        self.middlewares = []

    def add(self, method: str, pattern: str, handler: callable):
        if not self._is_valid_pattern(pattern):
            raise ValueError(f"Invalid pattern: {pattern}")
        if not self._is_valid_method(method):
            raise ValueError(f"Invalid method: {method}")
        if not self._is_valid_handler(handler):
            raise ValueError(f"Invalid handler: {handler}")
        self.routes.append((method, pattern, handler))

    def route(self, pattern: str, methods: Tuple[str, ...] = ('GET',)):
        if not self._is_valid_pattern(pattern):
            raise ValueError(f"Invalid pattern: {pattern}")
        if not self._is_valid_methods(methods):
            raise ValueError(f"Invalid methods: {methods}")
        def decorator(f):
            self.add(methods[0], pattern, f)
            return f
        return decorator

    def resolve(self, method: str, path: str) -> Tuple[callable, Dict[str, str]]:
        for route in self.routes:
            if route[1] == path:
                return route[2], route[0]
        raise NotFound(HTTPError(404, "Not Found"))

    def dispatch(self, request: Request) -> Response:
        handler, params = self.resolve(request.method, request.path)
        if not handler:
            raise NotFound(HTTPError(404, "Not Found"))
        if request.method != "HEAD" and not hasattr(handler, "head"):
            handler = getattr(handler, "get", None)
        if not handler:
            raise MethodNotAllowed(HTTPError(405, "Method Not Allowed"))
        response = handler(request)
        if request.method == "HEAD":
            response.body = b''
        return response

    def _is_valid_pattern(self, pattern: str) -> bool:
        if not pattern.startswith('/'):
            return False
        segments = pattern.split('/')
        if len(segments) == 1:
            return True
        for segment in segments[1:]:
            if segment == '{name}':
                continue
            if segment == '{name:int}':
                continue
            if segment == '{name:path}':
                continue
            if segment == '':
                return False
            if segment.startswith('{') and segment.endswith('}'):
                return False
            if segment.startswith('{') and segment.endswith('}'):
                return False
            if segment == '':  # Empty segment
                return False
            if segment == '/':
                return False
        return True

    def _is_valid_method(self, method: str) -> bool:
        if method not in ['GET', 'POST', 'PUT', 'DELETE', 'HEAD']:
            return False
        return True

    def _is_valid_handlers(self, handler: callable) -> bool:
        if not isinstance(handler, callable):
            return False
        return True
