# web/middleware.py
from typing import Callable, Tuple, Dict, List, Optional
from .request import Request, parse_request
from .http_error import HTTPError, BadRequest, NotFound, MethodNotAllowed
from .response import Response
from .router import Router

class Middleware:
    def __init__(self, func: Callable):
        self.func = func

    def __call__(self, request: Request, call_next: Callable) -> Response:
        try:
            response = self.func(request, call_next)
            return response
        except HTTPError as e:
            return response
        except Exception as e:
            return Response(status=500, body=f"<500 Internal Server Error>")

class App:
    def __init__(self, router: Router, middleware: Tuple[Middleware, ...] = ()):
        self.router = router
        self.middlewares = middleware

    def handle(self, request: Request) -> Response:
        for middleware in self.middlewares:
            request = middleware(request)
        response = self.router.dispatch(request)
        return response

    def handle_bytes(self, data: bytes) -> bytes:
        request = parse_request(data)
        response = self.handle(request)
        return response.to_bytes()
