# kv/compact.py
from typing import Dict, Any, Tuple, List, Optional
import os
import struct
import zlib
from .kv import decode_snapshot, encode_snapshot, CorruptSnapshot

def write_snapshot(path, items):
    tmp_path = path + '.tmp'
    with open(tmp_path, 'wb') as f:
        f.write(encode_snapshot(items))
    os.replace(tmp_path, path)

def read_snapshot(path) -> Dict[bytes, bytes]:
    if not path:
        return {}
    try:
        with open(path, 'rb') as f:
            data = f.read()
            if not data:
                return {}
            magic, count = struct.unpack('ii', data[:8])
            if magic != 0x53564151:  # b'KVS1'
                raise CorruptSnapshot("wrong magic")
            items = {}
            idx = 0
            for _ in range(count):
                key_len, key = struct.unpack('2s', data[idx:idx+2])
                idx += 2
                val_len, val = struct.unpack('4s', data[idx:idx+4])
                idx += 4
                crc = struct.unpack('i', data[idx:idx+4])[0]
                if zlib.crc32(data[:idx]) != crc:
                    raise CorruptSnapshot("checksum mismatch")
                items[key] = val
            return items
    except Exception as e:
        raise CorruptSnapshot("error reading snapshot") from e

def compact(snapshot_path, items, log):
    write_snapshot(snapshot_path, items)
    log.reset()
    log.compact(items)
