# kv/store.py
from typing import Optional, Dict, List, Tuple, Any
import os
import struct
import zlib
from collections import defaultdict
from .kv import Log, Record, decode_records, encode_record, CorruptLog, CorruptSnapshot, PUT, DELETE, encode_snapshot, decode_snapshot

class KVStore:
    def __init__(self, directory, max_log_records=None):
        self.directory = directory
        self.snapshot_path = os.path.join(directory, 'snapshot.db')
        self.wal_path = os.path.join(directory, 'wal.log')
        self._load_snapshot()
        self._open_log()
        self._replay_recovered_records()
        self._setup_context_manager()

    def _load_snapshot(self):
        if os.path.exists(self.snapshot_path):
            self.snapshot = read_snapshot(self.snapshot_path)
            self._setup_snapshot()

    def _setup_snapshot(self):
        self.snapshot = self.snapshot or {}
        self._setup_data()

    def _setup_data(self):
        self._data = defaultdict(bytes)
        for key, value in self.snapshot.items():
            self._data[key] = value

    def _open_log(self):
        self.log = Log(self.wal_path)
        self.log._open()

    def _replay_recovered_records(self):
        for record in self.log.recovered:
            if record.op == PUT:
                self._data[record.key] = record.value
            elif record.op == DELETE:
                del self._data[record.key]

    def _setup_context_manager(self):
        self._context_manager = contextmanager(self._close)
        self._context_manager.__enter__()
        self._context_manager.__exit__(None, None, None)

    def _close(self):
        self.log.close()
        self._log = None

    def put(self, key, value):
        if not isinstance(key, bytes) or not isinstance(value, bytes):
            raise TypeError("key and value must be bytes")
        if key == b'':
            raise ValueError("key cannot be empty")
        if len(key) > 65535:
            raise ValueError("key cannot be longer than 65535 bytes")
        if value == b'':
            value = b''
        if self._data.get(key):
            # Update the value if it's the same
            if self._data[key] == value:
                return
        # Write to log
        record = Record(PUT, key, value)
        offset = self.log.append(record.op, key, value)
        self._data[key] = value
        self._log = self.log
        self._log.count += 1
        self._log.size += len(encode_record(record))

    def get(self, key, default=None):
        if key in self._data:
            return self._data[key]
        return default

    def key_in_store(self, key):
        return key in self._data

    def len(self):
        return len(self._data)

    def delete(self, key):
        if key not in self._data:
            return False
        del self._data[key]
        record = Record(DELETE, key, b'')
        offset = self.log.append(record.op, key, b'')
        self._log.count += 1
        self._log.size += len(encode_record(record))
        return True

    def scan(self, start=None, end=None, prefix=b''):
        results = []
        for key in self._data:
            if start is not None and key > start:
                break
            if end is not None and key >= end:
                break
            if prefix and not key.startswith(prefix):
                continue
            results.append((key, self._data[key]))
        return results

    def compact(self):
        if not self._log:
            return
        items = self._data.copy()
        self._log.compact(items)
        self._data = items
        self._log.count = len(self._data)
        self._log.size = len(encode_snapshot(self._data))

    def stats(self) -> dict:
        return {
            'keys': len(self._data),
