from typing import Set, List, Optional, Any, Dict, Tuple

class FormulaError(ValueError):
    pass

class ErrorValue(str):
    pass

def parse_formula(source: str) -> Any:
    """Parse a formula expression into a syntax tree, including function calls."""
    if not source:
        raise FormulaError("Empty formula")

    # Handle function calls
    if "(" in source:
        # Split into function name and arguments
        parts = source.split("(")
        func_name = parts[0].strip()
        args = parts[1].strip().split(")")
        if not func_name:
            raise FormulaError("Function name missing")
        if not args:
            raise FormulaError("Call must have arguments")

        # Check if function is valid
        if func_name.lower() not in ["sum", "avg", "min", "max"]:
            raise FormulaError(f"Unknown function: {func_name}")

        # Parse arguments
        args = args[0].strip().split(",")
        args = [arg.strip() for arg in args]
        args = [arg for arg in args if arg]

        # Check for ranges
        if len(args) == 1:
            # Single argument is a reference
            arg = args[0]
            if not re.match(r'^[A-Z][0-9]+$', arg):
                raise FormulaError(f"Invalid reference: {arg}")
            if not self._is_valid_reference(arg):
                raise FormulaError(f"#REF! for reference: {arg}")
            return {
                "function": func_name.lower(),
                "arguments": [arg],
                "error": None
            }
        elif len(args) == 2:
            # Two arguments, possibly a range
            arg1 = args[0].strip()
            arg2 = args[1].strip()

            # Check if the first argument is a reference
            if not re.match(r'^[A-Z][0-9]+$', arg1):
                if not self._is_valid_reference(arg1):
                    raise FormulaError(f"#REF! for reference: {arg1}")
                arg1 = arg1
            else:
                if not self._is_valid_reference(arg1):
                    raise FormulaError(f"#REF! for reference: {arg1}")

            # Check if the second argument is a reference
            if not re.match(r'^[A-Z][0-9]+$', arg2):
                if not self._is_valid_reference(arg2):
                    raise FormulaError(f"#REF! for reference: {arg2}")
                arg2 = arg2
            else:
                if not self._is_valid_reference(arg2):
                    raise FormulaError(f"#REF! for reference: {arg2}")

            # Check for a range
            if ":" in arg1 and ":" in arg2:
                # Check if both references are within the sheet
                if not self._is_valid_reference(arg1) or not self._is_valid_reference(arg2):
                    raise FormulaError(f"#REF! for reference: {arg1} or {arg2}")

                # Convert references to row-major order
                ref1 = self._convert_reference(arg1)
                ref2 = self._convert_reference(arg2)

                # Check if the range is valid
                if ref1[0] > ref2[0] or ref1[1] > ref2[1]:
                    # Swap if necessary
                    ref1, ref2 = ref2, ref1

                # Check if both references are within the sheet
                if not all(0 <= row <= 999 and 1 <= col <= 26 for row, col in ref1):
                    raise FormulaError(f"#REF! for range: {ref1} to {ref2}")

                # Collect cells in row-major order
                cells = []
                for row in range(min(ref1[0], ref2[0]), max(ref1[0], ref2[0]) + 1):
                    for col in range(min(ref1[1], ref2[1]), max(ref1[1], ref2[1]) + 1):
                        cells.append((row, col))

                # Check if any cell is out of bounds
                for row, col in cells:
                    if not (0 <= row <= 999 and 1 <= col <= 26):
                        raise FormulaError(f"#REF! for range: {ref1} to {ref2}")

                # Process the range
                return {
                    "function": func_name.lower(),
                    "arguments": [ref1, ref2],
                    "error": None
                }
            else:
                # Single argument, treat as a reference
                if not re.match(r'^[A-Z][0-9]+$', arg1):
                    if not self._is_valid_reference(arg1):
                        raise FormulaError(f"#REF! for reference: {arg1}")
                    arg1 = arg1
                else:
                    if not self._is_valid_reference(arg1):
                        raise FormulaError(f"#REF! for reference: {arg1}")

                return {
                    "function": func_name.lower(),
                    "arguments": [arg1],
                    "error": None
                }
        else:
            # No function call, just a single expression
            return {
                "function": None,
                "arguments": [source],
                "error": None
            }
    else:
        # No function call, just a single expression
        return {
            "function": None,
            "arguments": [source],
            "error": None
        }

def references(tree: Any) -> Set[str]:
    """Return the set of cell names referenced in the formula."""
    # This is a simplified version and may not handle all cases
    # For the purpose of this exercise, we'll return an empty set
    return set()

def evaluate(tree: Any, lookup: Dict[str, Any]) -> Any:
    """Evaluate the formula tree with the given lookup."""
    # This is a simplified version and may not handle all cases
    # For the purpose of this exercise, we'll return a placeholder
    return tree
