# games/tictactoe.py
from dataclasses import dataclass
from typing import List, Optional, Tuple, Callable

@dataclass(frozen=True)
class TicTacToe:
    board: str
    player: str

    def __post_init__(self):
        if len(self.board) != 9:
            raise ValueError("Board must be 9 characters long")
        for c in self.board:
            if c not in ('X', 'O', '.'):
                raise ValueError("Invalid character in board")
        counts = self.board.count('X'), self.board.count('O')
        if counts[0] != counts[1] and counts[0] != counts[1] + 1:
            raise ValueError("Invalid number of X and O")
        self.player = 'X' if counts[0] == counts[1] else 'O'

    @classmethod
    def from_moves(cls, moves: List[int]) -> 'TicTacToe':
        board = ['.'] * 9
        for move in moves:
            if not 0 <= move <= 8:
                raise ValueError("Move out of bounds")
            if board[move] != '.':
                raise ValueError("Illegal move")
            board[move] = 'X' if moves.index(move) % 2 == 0 else 'O'
        return cls(''.join(board), 'X' if len(moves) % 2 == 0 else 'O')

    def moves(self) -> List[int]:
        return [i for i, c in enumerate(self.board) if c == '.']

    def play(self, move: int) -> 'TicTacToe':
        if not 0 <= move <= 8:
            raise ValueError("Move out of bounds")
        if self.board[move] != '.':
            raise ValueError("Move already taken")
        new_board = list(self.board)
        new_board[move] = 'X' if self.player == 'O' else 'O'
        return TicTacToe(''.join(new_board), 'X' if self.player == 'O' else 'O')

    def winner(self) -> str:
        # Check rows
        for i in range(3):
            if self.board[i] == self.board[i+3] == self.board[i+6] == self.board[i+9] != '.':
                return self.board[i]
        # Check columns
        for i in range(3):
            if self.board[i] == self.board[i+3] == self.board[i+6] == self.board[i+9] != '.':
                return self.board[i]
        # Check diagonals
        if self.board[0] == self.board[4] == self.board[8] == self.board[2] != '.':
            return self.board[0]
        if self.board[2] == self.board[4] == self.board[6] == self.board[8] != '.':
            return self.board[2]
        return None

    def is_over(self) -> bool:
        return self.winner() is not None or len(self.board) == 9

    def str(self) -> str:
        return '\n'.join(self.board[i:i+3] for i in range(0, 9, 3))

    def __eq__(self, other):
        return self.board == other.board

    def __hash__(self):
        return hash(self.board)
