from dataclasses import dataclass
from typing import List, Tuple, Optional, Callable

@dataclass(frozen=True)
class ConnectFour:
    columns: int
    rows: int
    board: List[str]
    player: str

    def __post_init__(self):
        if self.columns < 1 or self.rows < 1:
            raise ValueError("Columns and rows must be at least 1")
        self.board = ['.'] * (self.columns * self.rows)
        self.player = 'X' if self.board.count('X') == self.board.count('O') else 'O'

    @classmethod
    def from_moves(cls, moves: List[int], columns: int = 7, rows: int = 6) -> 'ConnectFour':
        board = ['.'] * (columns * rows)
        for move in moves:
            if not 0 <= move < columns:
                raise ValueError("Invalid column")
            if board[move * rows] != '.':
                raise ValueError("Illegal move")
            board[move * rows] = 'X' if moves.index(move) % 2 == 0 else 'O'
        return cls(columns, rows, board, 'X' if len(moves) % 2 == 0 else 'O')

    def move(self, column: int) -> 'ConnectFour':
        if not 0 <= column < self.columns:
            raise ValueError("Invalid column")
        row = self.rows - 1
        while row >= 0 and self.board[row] != '.':
            row -= 1
        if row < 0:
            raise ValueError("Column is full")
        self.board[row * self.rows + column] = 'X' if self.player == 'O' else 'O'
        return self

    def str(self) -> str:
        return '\n'.join([self.board[i*self.rows + j] for j in range(self.rows)] for i in range(self.columns))

    def winner(self) -> str:
        # Check rows
        for i in range(self.rows):
            if self.board[i*self.columns : (i+1)*self.columns] == ['X'] * self.columns or self.board[i*self.columns : (i+1)*self.columns] == ['O'] * self.columns:
                return self.board[i*self.columns] if self.board[i*self.columns] == 'X' else 'O'
        # Check columns
        for i in range(self.columns):
            if self.board[i] == self.board[i+self.rows] == self.board[i+2*self.rows] == self.board[i+3*self.rows] != '.':
                return self.board[i]
        # Check diagonals
        if self.board[0] == self.board[self.rows] == self.board[2*self.rows] == self.board[3*self.rows] != '.':
            return self.board[0]
        if self.board[self.rows] == self.board[2*self.rows] == self.board[3*self.rows] == self.board[4*self.rows] != '.':
            return self.board[self.rows]
        return None

    def is_over(self) -> bool:
        return self.winner() is not None or len(self.board) == self.columns * self.rows

    def cell(self, column: int, row: int) -> str:
        if not 0 <= column < self.columns or not 0 <= row < self.rows:
            raise IndexError("Invalid cell")
        return self.board[column + row * self.columns]

    def evaluate(self, state: 'ConnectFour') -> int:
        score = 0
        # Check all possible windows
        for i in range(self.rows):
            for j in range(self.columns):
                # Horizontal
                if self.board[i*self.columns + j] == self.board[i*self.columns + j + 1] == self.board[i*self.columns + j + 2] == self.board[i*self.columns + j + 3] != '.':
                    score += (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1)
                # Vertical
                if self.board[i*self.columns + j] == self.board[(i+1)*self.columns + j] == self.board[(i+2)*self.columns + j] == self.board[(i+3)*self.columns + j] != '.':
                    score += (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1)
                # Diagonal (top-left to bottom-right)
                if self.board[i*self.columns + j] == self.board[(i+1)*self.columns + j+1] == self.board[(i+2)*self.columns + j+2] == self.board[(i+3)*self.columns + j+3] != '.':
                    score += (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1)
                # Diagonal (top-right to bottom-left)
                if self.board[i*self.columns + j] == self.board[(i+1)*self.columns + j-1] == self.board[(i+2)*self.columns + j-2] == self.board[(i+3)*self.columns + j-3] != '.':
                    score += (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1) * (1 if self.board[i*self.columns + j] == state.player else -1)
        return score

    def __eq__(self, other):
        return self.board == other.board

    def __hash__(self):
