# games/search.py
from dataclasses import dataclass
from typing import Optional, Tuple, List, Callable, Any

@dataclass(frozen=True)
class SearchResult:
    score: float
    move: Optional[int]
    nodes: int

def search(state: Any, depth: Optional[int] = None, evaluate: Optional[Callable[[Any], float]] = None) -> SearchResult:
    if depth is None:
        depth = 3  # Default depth for search

    if state.is_over():
        if state.winner() is not None:
            return SearchResult(0.0, None, 0)
        else:
            return SearchResult(0.0, None, 0)

    if evaluate is None:
        evaluate = lambda state: 0.0

    if depth == 0:
        return SearchResult(evaluate(state), None, 0)

    best_score = -float('inf')
    best_move = None
    best_nodes = 0

    for move in state.moves():
        new_state = state.play(move)
        result = search(new_state, depth - 1, evaluate)
        score = result.score
        if score > best_score:
            best_score = score
            best_move = move
            best_nodes = result.nodes
        elif score == best_score:
            if move < best_move:
                best_move = move
                best_nodes = result.nodes

    return SearchResult(best_score, best_move, best_nodes)

def best_move(state: Any, depth: Optional[int] = None, evaluate: Optional[Callable[[Any], float]] = None) -> Optional[int]:
    result = search(state, depth, evaluate)
    return result.move
