    # This is a simplified version; actual implementation would be more complex
    return parse_pattern(pattern)

def RegexError(message: str, position: int) -> ValueError:
    # Custom exception for regex errors
    return ValueError(message, position)

# Error handling
def error(message: str, position: int) -> None:
    raise RegexError(message, position)

# Parsing logic
def _parse_char(char: str) -> AST:
    # Parse a single character
    if char == '.':
        return AnyChar()
    if char == '\\':
        if len(char) == 1:
            error("Invalid backslash at end of pattern", 0)
        return Literal(char[1])
    if char == '[':
        if len(char) == 1:
            error("Unclosed character class", 0)
        # Parse character class
        if char[1] == '^':
            negated = True
        else:
            negated = False
        if len(char) == 2:
            error("Empty character class", 0)
        items = []
        i = 2
        while i < len(char):
            if char[i] == '-':
                if len(items) == 0:
                    error("Invalid range in character class", 0)
                low, high = items[-1]
                if low > high:
                    error(f"Range {low}-{high} is invalid", 0)
                i += 1
            elif char[i] == ']':
                if len(items) == 0:
                    error("Unclosed character class", 0)
                break
            else:
                low, high = char[i], char[i+1]
                items.append((low, high))
                i += 2
        return CharClass(items, negated)
    if char == '(':
        error("Unclosed parenthesis", 0)
    if char == ')':
        error("Unclosed parenthesis", 0)
    return Literal(char)

def _parse_group(pattern: str) -> AST:
    # Parse a group (parentheses)
    if pattern[0] != '(':
        error("Unclosed group", 0)
    if pattern[-1] != ')':
        error("Unclosed group", 0)
    content = pattern[1:-1]
    return Group(parse_pattern(content))

def _parse_concat(pattern: str) -> AST:
    # Parse a concatenation
    items = []
    i = 0
    while i < len(pattern):
        if pattern[i] == '|':
            # Handle alternative
            items.append(Alt(items))
            items = [items[-1]]
            i += 1
        elif pattern[i] == '(':
            # Handle group
            items.append(Group(parse_pattern(pattern[i+1:-1])))
            i += 1 + len(pattern[i+1:-1]) + 1
        else:
            # Handle literal or any char
            items.append(_parse_char(pattern[i]))
            i += 1
    return Concat(items)

def _parse_alt(pattern: str) -> AST:
    # Parse an alternative
    items = []
    i = 0
    while i < len(pattern):
        if pattern[i] == '|':
            # Handle alternative
            items.append(Alt(items))
            items = [items[-1]]
            i += 1
        elif pattern[i] == '(':
            # Handle group
            items.append(Group(parse_pattern(pattern[i+1:-1])))
            i += 1 + len(pattern[i+1:-1]) + 1
        else:
            # Handle literal or any char
            items.append(_parse_char(pattern[i]))
            i += 1
    return Alt(items)

def _parse_star(pattern: str) -> AST:
    # Parse a star
    if pattern[0] == '*':
        return Star(parse_pattern(pattern[1:]))
    error("Invalid quantifier", 0)

def _parse_plus(pattern: str) -> AST:
    # Parse a plus
    if pattern[0] == '+':
        return Plus(parse_pattern(pattern[1:]))
    error("Invalid quantifier", 0)

def _parse_optional(pattern: str) -> AST:
    # Parse an optional
    if pattern[0] == '?':
        return Optional(parse_pattern(pattern[1:]))
    error("Invalid quantifier", 0)

def parse(pattern: str) -> AST:
    # Main parsing function
    if not pattern:
        return Empty()
    if pattern[0] == '\\':
        error("Invalid backslash at end of pattern", 0)
    if pattern[0] == '[':
        if pattern[1] == '^':
            negated = True
        else:
            negated = False
        if pattern[2] == ']':
            if len(pattern) == 3:
                error("Empty character class", 0)
            items = []
            i = 3
            while i < len(pattern):
                if pattern[i] == '-':
                    if len(items) == 0:
                        error("Invalid range in character class", 0)
                    low, high = items[-1]
                    if low > high:
                        error(f"Range {low}-{high} is invalid", 0)
                    i += 1
                elif pattern[i] == ']':
                    if len(items) == 0:
                        error("Unclosed character class", 0)
                    break
                else:
                    low, high = pattern[i], pattern[i+1]
                    items.append((low, high))
                    i += 2
            return CharClass(items, negated)
    if pattern[0] == '(':
        return _parse_group(pattern)
    if pattern[0] == '|':
        return _parse_alt(pattern)
    if pattern[0] == '*':
        return _parse_star(pattern)
    if pattern[0] == '+':
        return _parse_plus(pattern)
    if pattern[0] == '?':
        return _parse_optional(pattern)
    if pattern[0] == '.':
        return AnyChar()
    return _parse_char(pattern)
