from js.scanner import JSONError, Token, tokenize
import json
import re

def loads(text: str) -> any:
    tokens = tokenize(text)
    i = 0
    result = []

    while i < len(tokens):
        token = tokens[i]
        if token.kind == 'EOF':
            break
        if token.kind == 'JSONError':
            raise JSONError(token.value, token.line, token.column)
        if token.kind == 'NUMBER':
            # Convert to int or float
            if '.' in token.value:
                value = float(token.value)
            else:
                value = int(token.value)
            result.append(value)
            i += 1
        elif token.kind == 'STRING':
            # Decode string
            decoded = token.value[1:-1]
            result.append(decoded)
            i += 1
        elif token.kind == 'TRUE':
            result.append(True)
            i += 1
        elif token.kind == 'FALSE':
            result.append(False)
            i += 1
        elif token.kind == 'NULL':
            result.append(None)
            i += 1
        else:
            # Invalid token
            raise JSONError(f"Unexpected token: {token.value} at line {token.line} column {token.column}")

    # Parse the result
    if not result:
        raise JSONError("Unexpected end of text", 0, 0)

    # Handle objects and arrays
    if result[0] is None:
        # Empty object
        return {}
    elif isinstance(result[0], dict):
        # Parse object
        obj = {}
        i = 1
        while i < len(result):
            if result[i] is None:
                # End of object
                return obj
            if result[i] is not None:
                key = result[i]
                value = result[i+1]
                obj[key] = value
                i += 2
        raise JSONError("Unexpected end of text", 0, 0)
    elif isinstance(result[0], list):
        # Parse array
        arr = []
        i = 1
        while i < len(result):
            if result[i] is None:
                # End of array
                return arr
            arr.append(result[i])
            i += 1
        raise JSONError("Unexpected end of text", 0, 0)
    else:
        # Parse scalar
        return result[0]
