                if i + 2 < len(text) and text[i+2] == 'u':
                    if i + 3 < len(text) and text[i+3] == 'l':
                        if i + 4 < len(text) and text[i+4] == 'n':
                            tokens.append(Token(kind='NULL', value='null', line=i+1, column=0))
                            i += 6
                            continue
            if i + 1 < len(text) and text[i+1] == 'u':
                if i + 2 < len(text) and text[i+2] == 'l':
                    if i + 3 < len(text) and text[i+3] == 'n':
                        if i + 4 < len(text) and text[i+4] == 'k':
                            tokens.append(Token(kind='NULL', value='null', line=i+1, column=0))
                            i += 6
                            continue
            tokens.append(Token(kind='STRING', value=text[i], line=i+1, column=0))
            i += 1
            continue

        # Unexpected character
        if allow_nan and text[i] in 'NaNInfinity':
            # Handle NaN and Infinity
            if text[i:i+4] == 'NaN':
                tokens.append(Token(kind='NUMBER', value=float('nan'), line=i+1, column=0))
                i += 4
            elif text[i:i+9] == 'Infinity':
                tokens.append(Token(kind='NUMBER', value=float('inf'), line=i+1, column=0))
                i += 9
            elif text[i:i+12] == '-Infinity':
                tokens.append(Token(kind='NUMBER', value=float('-inf'), line=i+1, column=0))
                i += 12
            else:
                # Invalid literal
                tokens.append(Token(kind='JSONError', value=None, line=i+1, column=0))
                i += 1
                continue
        else:
            tokens.append(Token(kind='JSONError', value=None, line=i+1, column=0))
            i += 1

    # Add EOF token
    tokens.append(Token(kind='EOF', value=None, line=len(text)+1, column=0))
    return tokens
