# js/dump.py
from js.parser import loads
import json
import re

def dumps(obj: any, *, indent: int = None, sort_keys: bool = False, ensure_ascii: bool = False, allow_nan: bool = False) -> str:
    if obj is None:
        return 'null'
    if isinstance(obj, bool):
        return 'true' if obj else 'false'
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, float):
        if float.is_nan(obj):
            if allow_nan:
                return 'NaN'
            else:
                raise ValueError("nan")
        if float.is_inf(obj):
            if allow_nan:
                return 'Infinity' if obj == float('inf') else '-Infinity'
            else:
                raise ValueError("inf")
        return f"{obj}"

    if isinstance(obj, str):
        # Quote the string
        if ensure_ascii:
            return f'"{obj}"'
        else:
            return f'"{obj}"'

    if isinstance(obj, list):
        # Convert to array
        return '[{}]'.format(', '.join(dumps(item, indent=indent, sort_keys=sort_keys, ensure_ascii=ensure_ascii) for item in obj))
    if isinstance(obj, dict):
        # Convert to object
        if sort_keys:
            sorted_items = sorted(obj.items(), key=lambda x: x[0])
        else:
            sorted_items = obj.items()
        result = '{'
        for key, value in sorted_items:
            if result:
                result += ', '
            result += f'"{key}": {dumps(value, indent=indent, sort_keys=sort_keys, ensure_ascii=ensure_ascii)}'
        result += '}'
        return result

    raise TypeError(f"Unsupported type: {type(obj)}")
