from dataclasses import dataclass
from typing import Dict, Optional, Tuple, Union, List, Set
from collections import OrderedDict
import json

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str]  # Direction to room ID
    items: Tuple[str, ...]  # Tuple of item IDs

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool

class WorldError(ValueError):
    pass

def from_dict(data: Dict[str, Any]) -> "World":
    # Validate start
    if "start" not in data or not isinstance(data["start"], str):
        raise WorldError("start is missing or not a room id")

    # Validate rooms
    rooms = data.get("rooms", {})
    if not isinstance(rooms, dict):
        raise WorldError("rooms must be a dict")

    # Validate items
    items = data.get("items", {})
    if not isinstance(items, dict):
        raise WorldError("items must be a dict")

    # Initialize world
    world = World(start=data["start"], rooms=rooms, items=items)

    # Validate rooms
    for room_id, room in world.rooms.items():
        if not isinstance(room, Room):
            raise WorldError(f"Room {room_id} is not a Room")

        # Validate name and description
        if not room.name or not room.description:
            raise WorldError(f"Room {room_id} lacks a name or description")

        # Validate exits
        if not isinstance(room.exits, dict):
            raise WorldError(f"Room {room_id} lacks exits")

        for direction, room_id in room.exits.items():
            if direction not in DIRECTIONS:
                raise WorldError(f"Exit {direction} is not a valid direction")

            if room_id not in world.rooms:
                raise WorldError(f"Exit {direction} leads to an unknown room")

        # Validate items
        if not isinstance(room.items, tuple):
            raise WorldError(f"Room {room_id} lacks items")

        # Check for duplicate items
        item_ids = set()
        for item_id in room.items:
            if item_id in item_ids:
                raise WorldError(f"Item {item_id} is listed more than once in room {room_id}")
            item_ids.add(item_id)

    # Validate items
    for item_id, item in items.items():
        if not isinstance(item, Item):
            raise WorldError(f"Item {item_id} is not an Item")

        if not item.portable:
            # Check if item is in a room
            for room_id, room in world.rooms.items():
                if item_id in room.items:
                    raise WorldError(f"Item {item_id} is listed more than once in the world")

    return world
