import sys

class Command(NamedTuple):
    verb: str
    arg: Optional[str]

class ParseError(ValueError):
    pass

def parse(line: str) -> Command:
    # Normalize line
    line = line.strip()

    # Check for empty line
    if not line:
        raise ParseError("Say something.")

    # Split line into parts
    parts = line.lower().split()

    # Check for 'look' or 'l' or 'inventory' or 'inv' or 'i'
    if parts[0] in ("look", "l", "inventory", "inv", "i"):
        if len(parts) == 1:
            return Command("look", None)
        else:
            if parts[1] == "X":
                return Command("look", parts[2])
            else:
                return Command("look", parts[1])

    # Check for 'go' command
    if parts[0] == "go":
        if len(parts) == 1:
            raise ParseError("Go where?")
        elif len(parts) == 2:
            if parts[1] in DIRECTIONS:
                return Command("go", parts[1])
            else:
                raise ParseError(f"{parts[1]} is not a direction.")
        else:
            raise ParseError(f"{parts[1:]} is not a direction.")

    # Check for 'take', 'get', 'drop', 'examine', 'x', 'look at'
    if parts[0] in ("take", "get", "drop", "examine", "x", "look at"):
        if len(parts) == 1:
            raise ParseError("Take what?")
        elif len(parts) == 2:
            if parts[1] == "X":
                return Command(parts[0], parts[2])
            else:
                raise ParseError(f"{parts[1]} is not a valid argument.")
        else:
            raise ParseError(f"{parts[1:]} is not a valid argument.")

    # Check for 'inventory', 'inv', 'i'
    if parts[0] in ("inventory", "inv", "i"):
        if len(parts) == 1:
            return Command("inventory", None)
        else:
            raise ParseError(f"{parts[1:]} is not a valid argument.")

    # Check for unknown first word
    if not parts[0] or parts[0] not in DIRECTIONS:
        raise ParseError(f"I don't know the word \"{parts[0]}\".")

    # Default to 'go' command
    return Command("go", parts[0])
