# adventure/game.py
from typing import Dict, Any, List, Set
from adventure.world import World, WorldError
from adventure.parser import Command, ParseError
from adventure.parser import parse
from adventure.world import Room, Item
import json

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room = world.start
        self.inventory = []
        self.moves = 0

    def do(self, line: str) -> str:
        command = parse(line)
        if command.verb == "look":
            # Look command
            if command.arg is None:
                # Look at room
                room = self.world.rooms[self.room]
                description = room.description
                exits = []
                for direction, room_id in room.exits.items():
                    exits.append(direction)
                exits_str = ", ".join(exits) if exits else "none."
                output = f"{room.name}\n{description}\nExits: {exits_str}."
                if room.items:
                    items = room.items
                    item_str = ", ".join(items) if items else "none."
                    output += f"\nYou see: {item_str}."
                return output
            else:
                # Look at item
                item_id = command.arg
                room = self.world.rooms[self.room]
                for item_id in room.items:
                    if item_id == item_id:
                        # Item matches
                        item = room.items[item_id]
                        output = f"You see: {item.name}."
                        return output
                return f"You see no {command.arg} here."

        elif command.verb == "go":
            # Go command
            direction = command.arg
            if direction not in DIRECTIONS:
                raise ParseError(f"{direction} is not a direction.")

            if self.world.rooms.get(self.room) is None:
                raise ParseError("You can't go that way.")

            if direction in self.world.rooms[self.room].exits:
                new_room_id = self.world.rooms[self.room].exits[direction]
                self.room = new_room_id
                self.moves += 1
                return self.do("look")
            else:
                return f"You can't go that way."

        elif command.verb == "take":
            # Take command
            item_id = command.arg
            room = self.world.rooms[self.room]
            item = room.items[item_id]
            if not item.portable:
                # Can't take item
                return f"You can't take the {item.name}."
            else:
                # Add to inventory
                self.inventory.append(item_id)
                return f"Taken: {item.name}."

        elif command.verb == "drop":
            # Drop command
            item_id = command.arg
            room = self.world.rooms[self.room]
            if item_id in self.inventory:
                # Remove from inventory
                self.inventory.remove(item_id)
                # Add to room
                room.items.append(item_id)
                return f"Dropped: {item.name}."
            else:
                return f"You aren't carrying that."

        elif command.verb == "inventory":
            # Inventory command
            if not self.inventory:
                return "You are carrying nothing."
            else:
                return f"You are carrying: {', '.join(item.name for item in self.inventory)}."

    def save(self) -> str:
        # Save game state
        save_data = {
            "version": 1,
            "room": self.room,
            "inventory": list(self.inventory),
            "items": {},
            "moves": self.moves
        }

        # Add items to items dictionary
        for room_id, room in self.world.rooms.items():
            if room.items:
                save_data["items"][room_id] = list(room.items)

        return json.dumps(save_data, indent=2)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        # Load game from JSON
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if "version" not in data or data["version"] != 1:
            raise SaveError("Version mismatch")

        if "room" not in data or "inventory" not in data or "items" not in data or "moves" not in data:
            raise SaveError("Missing required keys")

        if not isinstance(data["room"], str):
            raise SaveError("Room must be a string")

        if not isinstance(data["inventory"], list):
            raise SaveError("Inventory must be a list")

        if not isinstance(data["items"], dict):
            raise SaveError("Items must be a dict")

        if not isinstance(data["moves"], int) or data["moves"] < 0:
            raise SaveError("Moves must be a non-negative integer")

        # Create new game
        game = cls(world)
        game.room = data["room"]
        game.inventory = data["inventory"]
        game.moves = data["moves"]

        # Load items into rooms
        for room_id, room in world.rooms.items():
            if room_id in data["items"]:
                room.items = list(data["items"][room_id])

        return game
