        # Validate locks
        if not isinstance(room.locks, dict):
            room.locks = {}

        # Validate items
        if not isinstance(room.items, tuple):
            raise WorldError(f"Room {room_id} lacks items")

        # Check for duplicate items
        item_ids = set()
        for item_id in room.items:
            if item_id in item_ids:
                raise WorldError(f"Item {item_id} is listed more than once in room {room_id}")
            item_ids.add(item_id)

        # Validate item treasures
        for item_id, item in items.items():
            if item_id in room.items:
                if not isinstance(item, Item):
                    raise WorldError(f"Item {item_id} is not an Item")
                if item.treasure < 0:
                    raise WorldError(f"Item {item_id} has negative treasure points.")

    # Validate items
    for item_id, item in items.items():
        if not isinstance(item, Item):
            raise WorldError(f"Item {item_id} is not an Item")

        if not item.portable:
            # Check if item is in a room
            for room_id, room in world.rooms.items():
                if item_id in room.items:
                    raise WorldError(f"Item {item_id} is listed more than once in the world")

    return world
