            item_id = command.arg
            room = self.world.rooms[self.room]
            item = room.items[item_id]
            if item_id not in self.inventory:
                return f"You aren't carrying that."
            else:
                # Check if item is a key
                if item.name == "key":
                    # Find all locked exits
                    locked_exits = []
                    for direction, room_id in room.exits.items():
                        if room_id in self.world.rooms and room_id in self.world.locks and self.world.locks[direction] == item_id:
                            locked_exits.append(direction)
                    if not locked_exits:
                        return f"Nothing here to use the {item.name} on."
                    else:
                        # Unlock those exits
                        self.unlocked_exits.extend([(room_id, direction) for direction in locked_exits])
                        self.unlocked_exits = sorted(self.unlocked_exits)
                        # Update visited rooms
                        self.visited_rooms.append(room_id)
                        self.visited_rooms = sorted(self.visited_rooms)
                        # Update scored items
                        self.scored_items.extend([item_id])
                        self.scored_items = sorted(self.scored_items)
                        # Update score
                        self.score += 10
                        return f"Unlocked: {', '.join(locked_exits)}."

        elif command.verb == "score":
            # Score command
            if self.room not in self.visited_rooms:
                self.visited_rooms.append(self.room)
                self.visited_rooms = sorted(self.visited_rooms)
                self.score += 10
                return f"Your score is {self.score}."
            else:
                # Check if item has treasure
                for item_id in self.scored_items:
                    item = self.world.items[item_id]
                    if item.treasure > 0:
                        self.score += item.treasure
                        self.scored_items.remove(item_id)
                        self.scored_items.append(item_id)
                return f"Your score is {self.score}."

    def save(self) -> str:
        # Save game state
        save_data = {
            "version": 2,
            "room": self.room,
            "inventory": list(self.inventory),
            "items": {},
            "moves": self.moves,
            "unlocked": self.unlocked_exits,
            "visited": self.visited_rooms,
            "scored": self.scored_items,
            "score": self.score
        }

        # Add items to items dictionary
        for room_id, room in self.world.rooms.items():
            if room.items:
                save_data["items"][room_id] = list(room.items)

        return json.dumps(save_data, indent=2)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        # Load game from JSON
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if "version" not in data or data["version"] != 2:
            raise SaveError("Version mismatch")

        if "room" not in data or "inventory" not in data or "items" not in data or "moves" not in data or "unlocked" not in data or "visited" not in data or "scored" not in data or "score" not in data:
            raise SaveError("Missing required keys")

        if not isinstance(data["room"], str):
            raise SaveError("Room must be a string")

        if not isinstance(data["inventory"], list):
            raise SaveError("Inventory must be a list")

        if not isinstance(data["items"], dict):
            raise SaveError("Items must be a dict")

        if not isinstance(data["moves"], int) or data["moves"] < 0:
            raise SaveError("Moves must be a non-negative integer")

        if not isinstance(data["unlocked"], list):
            raise SaveError("Unlocked must be a list")

        if not isinstance(data["visited"], list):
            raise SaveError("Visited must be a list")

        if not isinstance(data["scored"], list):
            raise SaveError("Scored must be a list")

        if not isinstance(data["score"], int) or data["score"] < 0:
            raise SaveError("Score must be a non-negative integer")

        # Create new game
        game = cls(world)
        game.room = data["room"]
        game.inventory = data["inventory"]
        game.moves = data["moves"]
        game.unlocked_exits = data["unlocked"]
        game.visited_rooms = data["visited"]
        game.scored_items = data["scored"]
        game.score = data["score"]

        # Load items into rooms
        for room_id, room in world.rooms.items():
            if room_id in data["items"]:
                room.items = list(data["items"][room_id])

        return game
