from datetime import datetime, timezone
from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict, Set, Union, Any
import re

@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: float

class ParseError(ValueError):
    pass

def normalize(time: str, client: str, method: str, path: str, status: str, size: str, latency_ms: str) -> Record:
    # Time normalization
    try:
        time = datetime.fromisoformat(time)
    except ValueError:
        raise ParseError("Invalid time format") from None

    time = time.replace(tzinfo=timezone.utc)

    # Client
    if not client:
        raise ParseError("Client must be non-empty")

    # Method
    if not method or not method.isascii() or not method.isalpha():
        raise ParseError("Method must be non-empty ASCII letters and upper-cased")

    # Path
    if not path:
        raise ParseError("Path must be non-empty")
    path = path.strip()
    if not path.startswith('/'):
        raise ParseError("Path must start with /")
    path = path.replace('//', '/')
    path = path.split('?', 1)[0]
    path = path.split('#', 1)[0]

    # Status
    try:
        status = int(status)
    except ValueError:
        if status.isdigit():
            status = int(status)
        else:
            raise ParseError("Status must be a digit string or an integer")
    if not (100 <= status <= 599):
        raise ParseError(f"Status {status} is out of range (100-599)")

    # Size
    if size == "-":
        size = 0
    elif size == "None":
        size = 0
    else:
        try:
            size = int(size)
        except ValueError:
            raise ParseError("Size must be a digit string or an integer") from None
    if size < 0:
        raise ParseError("Size must be non-negative")

    # Latency
    if latency_ms is None:
        latency_ms = None
    else:
        try:
            latency_ms = float(latency_ms)
        except ValueError:
            raise ParseError("Latency must be a float") from None
        if latency_ms < 0:
            raise ParseError("Latency must be non-negative")

    return Record(
        time=time,
        client=client,
        method=method.upper(),
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

def parse_clf(line: str) -> Record:
    """Parse common log format line."""
    parts = line.split()
    if len(parts) < 7:
        raise ParseError("Common log format requires exactly 7 fields")
    if len(parts) > 7:
        raise ParseError("Common log format must have exactly 7 fields")
    if parts[0].isdigit() or not parts[0].isascii() or not parts[0].isalpha():
        raise ParseError("Method must be a non-empty ASCII letter")
    if not parts[1].isascii() or not parts[1].isalpha():
        raise ParseError("Client must be a non-empty ASCII letter")
    if not parts[2].isascii() or not parts[2].isalpha():
        raise ParseError("Protocol must be a non-empty ASCII letter")

    method, path, protocol = parts[1], parts[2], parts[3]
    if not method.isalpha() or not method.isascii():
        raise ParseError("Method must be a non-empty ASCII letter")
    if not path.isalpha() or not path.isascii():
        raise ParseError("Path must be a non-empty ASCII letter")
    if not protocol.isalpha() or not protocol.isascii():
        raise ParseError("Protocol must be a non-empty ASCII letter")

    if len(parts) > 7:
        # Handle latency_ms
        if len(parts) > 8:
            latency_ms_str = parts[7]
            if not latency_ms_str.isdigit():
                raise ParseError("Latency must be a digit string")
            latency_ms = int(latency_ms_str)
            latency_ms /= 1000  # Convert microseconds to milliseconds
        else:
            latency_ms = None
    else:
        latency_ms = None

    return normalize(
        time=parts[4],
        client=parts[2],
        method=method,
        path=path,
        status=int(parts[5]),
        size=int(parts[6]),
        latency_ms=latency_ms
    )

def parse_jsonl(line: str) -> Record:
    """Parse JSON lines format."""
    try:
        data = json.loads(line)
    except json.JSONDecodeError:
        raise ParseError("Invalid JSON") from None
    if not isinstance(data, dict):
        raise ParseError("Line must be a JSON object") from None

    ts = data.get("ts")
    client = data.get("client")
    method = data.get("method")
    path = data.get("path")
    status = data.get("status")
    bytes_ = data.get("bytes")
    latency_ms = data.get("latency_ms")

    if ts is None:
        raise ParseError("ts is required")
    try:
        ts = datetime.fromisoformat(ts)
    except ValueError:
        raise ParseError("ts must be an ISO 8601 string with a UTC offset or ending in 'Z'") from None
    if ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)

    if client is None:
        raise ParseError("client is required")
    if not client:
        raise ParseError("client must be non-empty")

    if method is None:
        raise ParseError("method is required")
    if not method:
        raise ParseError("method must be non-empty")

    if path is None:
        raise ParseError("path is required")
    if not path:
        raise ParseError("path must be non-empty")

    if status is None:
        raise ParseError("status is required")
    if not status.isdigit():
        raise ParseError("status must be a string of digits")
    status = int(status)
    if not (100 <= status <= 599):
        raise ParseError(f"status {status} is out of range (100-599)")

    if bytes_ is not None:
        try:
            bytes_ = int(bytes_)
        except ValueError:
            raise ParseError("bytes must be a string of digits or None") from None
        if bytes_ < 0:
            raise ParseError("bytes must be non-negative")

    if latency_ms is not None:
        try:
            latency_ms = float(latency_ms)
        except ValueError:
            raise ParseError("latency_ms must be a float") from None
        if latency_ms < 0:
            raise ParseError("latency_ms must be non-negative")

    return normalize(
        time=ts,
        client=client,
        method=method,
        path=path,
        status=status,
        size=bytes_ if bytes_ is not None else 0,
        latency_ms=latency_ms
    )

def parse_line(line: str, fmt: str = "auto") -> Record:
    """Parse a line with a given format."""
    if fmt == "clf":
        return parse_clf(line)
    elif fmt == "jsonl":
        return parse_jsonl(line)
    elif fmt == "auto":
        if line.strip() == "":
            return None
        if line.startswith("{"):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError(f"Invalid format: {fmt}")

def read_records(lines: List[str], fmt: str = "auto") -> Tuple[List[Record], List[int]]:
    """Read records from lines with a given format."""
    records = []
    bad_lines = []

    for idx, line in enumerate(lines):
        line = line.strip()
        if not line:
            continue

        try:
            parsed = parse_line(line, fmt)
            if parsed is not None:
                records.append(parsed)
            else:
                bad_lines.append(idx + 1)  # 1-based index
        except ParseError as e:
            bad_lines.append(idx + 1)

    return records, bad_lines
