from typing import Dict, List, Set, Tuple
from collections import defaultdict

def percentile(values: List[float], p: int) -> float:
    """Compute percentile using the nearest-rank method."""
    if not values:
        raise ValueError("values must not be empty")
    if not 0 < p <= 100:
        raise ValueError("p must be in (0, 100]")

    n = len(values)
    rank = p / 100 * n
    if rank.is_integer():
        rank = int(rank)
    else:
        rank = int(rank) + 1
    return values[rank - 1]

def filter_records(records: List[Record], since: Optional[datetime] = None, until: Optional[datetime] = None, status: Optional[str] = None) -> List[Record]:
    """Filter records based on time and status."""
    if since is not None and until is not None:
        if since > until:
            raise ValueError("since must be <= until")

    filtered = []
    for record in records:
        if since is None or record.time <= since:
            if until is None or record.time < until:
                if status is None or (record.status in ("1xx", "2xx", "3xx", "4xx", "5xx") and (status == record.status or (status.startswith("4") and record.status.startswith("4")) or (status.startswith("5") and record.status.startswith("5")))):
                    filtered.append(record)

    return filtered

def summarize(records: List[Record], top: int = 3) -> Dict[str, Any]:
    """Summarize the records."""
    if not records:
        return {
            "requests": 0,
            "bytes": 0,
            "classes": {},
            "codes": {},
            "latency_ms": {
                "count": 0,
                "p50": None,
                "p95": None,
                "max": None
            },
            "top_paths": [],
            "first": None,
            "last": None
        }

    # Count requests
    requests = len(records)

    # Total bytes
    bytes_total = sum(record.size for record in records)

    # Count classes (1xx to 5xx)
    classes = defaultdict(int)
    for record in records:
        if 100 <= record.status <= 599:
            classes[record.status] += 1

    # Count codes (status codes)
    codes = defaultdict(int)
    for record in records:
        codes[record.status] += 1

    # Latency
    latency_records = [record.latency_ms for record in records if record.latency_ms is not None]
    latency_count = len(latency_records)
    if latency_count > 0:
        latency_p50 = percentile(latency_records, 50)
        latency_p95 = percentile(latency_records, 95)
        latency_max = max(latency_records) if latency_records else 0
    else:
        latency_p50 = None
        latency_p95 = None
        latency_max = None

    # Top paths
    top_paths = defaultdict(int)
    for record in records:
        top_paths[record.path] += 1
    top_paths_list = sorted(top_paths.items(), key=lambda x: (-x[1], x[0]))
    top_paths = [f"{path},{count}" for path, count in top_paths_list[:top]]

    # First and last time
    if records:
        first = min(record.time for record in records)
        last = max(record.time for record in records)
    else:
        first = None
        last = None

    return {
        "requests": requests,
        "bytes": bytes_total,
        "classes": classes,
        "codes": codes,
        "latency_ms": {
            "count": latency_count,
            "p50": latency_p50,
            "p95": latency_p95,
            "max": latency_max
        },
        "top_paths": top_paths,
        "first": first.isoformat() if first else None,
        "last": last.isoformat() if last else None
    }
