import argparse
import sys
import json
import datetime
from typing import List, Dict, Optional, Any
from .parsers import read_records, parse_line, parse_clf, parse_jsonl
from .stats import summarize, percentile, filter_records
from .__init__ import main, run

def main(args: Optional[List[str]] = None) -> int:
    if args is None:
        args = sys.argv[1:]

    parser = argparse.ArgumentParser(description="Log Aggregation Tool")
    parser.add_argument("FILE", nargs="+", help="Input file or files")
    parser.add_argument("--format", default="auto", help="Log format: clf, jsonl, or auto")
    parser.add_argument("--since", help="Filter records with time >= since")
    parser.add_argument("--until", help="Filter records with time < until")
    parser.add_argument("--status", help="Filter records by status (e.g., 404)")
    parser.add_argument("--top", type=int, default=3, help="Number of top paths to show")
    parser.add_argument("--json", action="store_true", help="Output JSON with 'bad_lines' key")

    args = parser.parse_args(args)

    if not args.FILE:
        parser.error("At least one file must be provided")

    records, bad_lines = read_records(args.FILE, fmt=args.format)

    if not records:
        print("No records found")
        return 1

    # Apply filters
    if args.since:
        try:
            since = datetime.datetime.fromisoformat(args.since)
        except ValueError:
            print("Invalid --since time")
            return 2
    else:
        since = None

    if args.until:
        try:
            until = datetime.datetime.fromisoformat(args.until)
        except ValueError:
            print("Invalid --until time")
            return 2
    else:
        until = None

    if args.status:
        status = args.status
        if not (status.isdigit() or (status.startswith("4") and status.startswith("4")) or (status.startswith("5") and status.startswith("5"))):
            print("Invalid --status")
            return 2
        if status.isdigit():
            status = int(status)
        elif status.startswith("4"):
            status = status[1:]
        elif status.startswith("5"):
            status = status[1:]
        else:
            print("Invalid --status")
            return 2
        if not (100 <= status <= 599):
            print("Invalid --status")
            return 2

    filtered = filter_records(records, since=since, until=until, status=status)

    summary = summarize(filtered, top=args.top)

    if args.json:
        print(json.dumps(summary, indent=2))
        print()
        return 0

    # Output the summary
    print(f"requests: {summary['requests']}")
    if summary['bad_lines'] > 0:
        print(f"bad lines: {summary['bad_lines']}")
    else:
        print("bad lines: 0")
    print(f"bytes: {summary['bytes']}")
    print(f"status: {summary['classes']}")
    print(f"latency: p50={summary['latency_ms']['p50']} ms p95={summary['latency_ms']['p95']} ms max={summary['latency_ms']['max']} ms")
    print("top paths:")
    for path, count in summary['top_paths']:
        print(f"  {path}, {count}")
    if not summary['top_paths']:
        print("  none")

    return 0
