# vfs/paths.py
import os

def normalize(path, cwd='/'):
    """Normalize a path to an absolute path with no '.' or '..' parts, no repeated '/', and no trailing '/' (except root '/' itself)."""
    if not path:
        raise ValueError("Path cannot be empty")
    if os.path.sep != '/':
        raise NotImplementedError("Path normalization is only supported for '/' separator")

    # Normalize relative path
    if os.path.sep in path:
        path = path.replace(os.path.sep, '/')

    # Handle absolute path
    if path.startswith('/'):
        # Normalize absolute path
        path = path.replace('/' + os.path.sep, '/')
        path = path.rstrip(os.path.sep)
        if path == '':
            return '/'
        return path

    # Handle relative path
    # Convert to absolute path relative to cwd
    if os.path.sep in path:
        path = path.replace(os.path.sep, '/')

    # Normalize relative path
    path = os.path.normpath(path)

    # Check for '.' and '..'
    if path == '.':
        return path
    if path == '..':
        return '/'

    # Check for repeated slashes
    if '/' in path:
        path = path.replace('//', '/')

    # Remove trailing slash if not root
    if path != '/':
        path = path.rstrip('/')

    return path

def join(base, *parts):
    """Join path components like posixpath.join, with proper handling of slashes."""
    if not parts:
        return ''

    # Join the base path with the parts
    joined = base + '/' + '/'.join(parts)

    # Normalize the joined path
    return normalize(joined)

def split(path):
    """Split an absolute normalized path into (parent, name)."""
    if not path:
        return ('', '')

    # Split the path into parent and name
    if path == '/':
        return ('', '')

    # Split on the last '/' to get the name
    parent, name = path.split('/', 1)

    # Check if the parent is valid
    if not parent:
        return ('', '')

    return (parent, name)
