# vfs/fs.py
import os
import shutil
import sys
import fnmatch
import shlex

class FileSystem:
    """A simple in-memory filesystem with basic file operations."""
    def __init__(self):
        self.root = {}
        self.current_dir = '/'

    def pwd(self):
        """Return the current directory and a newline."""
        return f"{self.current_dir}\n"

    def cd(self, path):
        """Change directory. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if os.path.isfile(self.root):
            if self.root != normalized_path:
                raise FSError(f"Path {normalized_path} is a file")
            else:
                raise FSError(f"Path {normalized_path} is a directory")

        # Check if the path is a directory
        if not os.path.isdir(self.root):
            raise FSError(f"Path {normalized_path} is not a directory")

        # Change directory
        self.current_dir = normalized_path

    def mkdir(self, path, parents=False):
        """Create a directory. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path already exists
        if os.path.exists(normalized_path):
            if parents:
                self._create_parents(normalized_path)
            else:
                raise FSError(f"Path {normalized_path} already exists")

        # Check if the path is a directory
        if os.path.isdir(normalized_path):
            if parents:
                self._create_parents(normalized_path)
            else:
                raise FSError(f"Path {normalized_path} is a directory")

        # Create the directory
        os.makedirs(normalized_path)

    def _create_parents(self, path):
        """Create all parent directories for a given path."""
        parts = normalize(path, self.current_dir).split('/')
        for i in range(len(parts)):
            parent = '/'.join(parts[:i+1])
            if not os.path.exists(parent):
                os.makedirs(parent)

    def write(self, path, text, append=False):
        """Write text to a file. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if os.path.isdir(normalized_path):
            raise FSError(f"Path {normalized_path} is a directory")

        # Check if the path exists
        if os.path.exists(normalized_path):
            if append:
                with open(normalized_path, 'a') as f:
                    f.write(text)
            else:
                with open(normalized_path, 'w') as f:
                    f.write(text)
        else:
            with open(normalized_path, 'w') as f:
                f.write(text)

    def read(self, path):
        """Read text from a file. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if os.path.isdir(normalized_path):
            raise FSError(f"Path {normalized_path} is a directory")

        # Check if the path exists
        if not os.path.exists(normalized_path):
            raise FSError(f"Path {normalized_path} not found")

        with open(normalized_path, 'r') as f:
            return f.read()

    def ls(self, path='.'):
        """List entries in a directory. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if not os.path.isdir(normalized_path):
            raise FSError(f"Path {normalized_path} is not a directory")

        # Get the entries
        entries = os.listdir(normalized_path)
        entries.sort()

        # Format the output
        output = []
        for entry in entries:
            if os.path.isdir(os.path.join(normalized_path, entry)):
                output.append(f"{entry}/")
            else:
                output.append(entry)

        return '\n'.join(output)

    def rm(self, path, recursive=False):
        """Remove a file or directory. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if os.path.isdir(normalized_path):
            if recursive:
                self._remove_directory(normalized_path)
            else:
                if os.path.exists(normalized_path):
                    raise FSError(f"Path {normalized_path} is a directory")
                else:
                    raise FSError(f"Path {normalized_path} not found")
        else:
            if os.path.exists(normalized_path):
                if os.path.isfile(normalized_path):
                    os.remove(normalized_path)
                else:
                    raise FSError(f"Path {normalized_path} is a directory")
            else:
                raise FSError(f"Path {normalized_path} not found")

    def _remove_directory(self, path):
        """Remove a directory and all its contents."""
        for entry in os.listdir(path):
            entry_path = os.path.join(path, entry)
            if os.path.isdir(entry_path):
                self._remove_directory(entry_path)
            else:
                os.remove(entry_path)
        os.rmdir(path)

    def mv(self, src, dst):
        """Move or rename a file or directory. Raises errors as specified."""
        if not src:
            raise ValueError("Path cannot be empty")

        # Normalize source path
        normalized_src = normalize(src, self.current_dir)

        # Check if the source path is valid
        if not normalized_src:
            raise FSError(f"Invalid path: {normalized_src}")

        # Check if the source path is a directory
        if os.path.isdir(normalized_src):
            if normalized_src == self.current_dir:
                raise FSError(f"Source path {normalized_src} is the current directory")
            if os.path.exists(normalized_src):
                raise FSError(f"Source path {normalized_src} exists")
            else:
                raise FSError(f"Source path {normalized_src} not found")

        # Check if the source path is a file
        if os.path.isfile(normalized_src):
            if normalized_src == self.current_dir:
                raise FSError(f"Source path {normalized_src} is the current directory")
            if os.path.exists(normalized_src):
                raise FSError(f"Source path {normalized_src} exists")
            else:
                raise FSError(f"Source path {normalized_src} not found")

        # Normalize destination path
        normalized_dst = normalize(dst, self.current_dir)

        # Check if the destination path is valid
        if not normalized_dst:
            raise FSError(f"Invalid path: {normalized_dst}")

        # Check if the destination path is a directory
        if os.path.isdir(normalized_dst):
            if normalized_dst == self.current_dir:
                raise FSError(f"Destination path {normalized_dst} is the current directory")
            if os.path.exists(normalized_dst):
                raise FSError(f"Destination path {normalized_dst} exists")
            else:
                raise FSError(f"Destination path {normalized_dst} not found")

        # Check if the destination path is a file
        if os.path.isfile(normalized_dst):
            if normalized_dst == self.current_dir:
                raise FSError(f"Destination path {normalized_dst} is the current directory")
            if os.path.exists(normalized_dst):
                raise FSError(f"Destination path {normalized_dst} exists")
            else:
                raise FSError(f"Destination path {normalized_dst} not found")

        # Check if the destination path is a directory and the source is a file
        if os.path.isdir(normalized_dst):
            if normalized_dst == self.current_dir:
                raise FSError(f"Destination path {normalized_dst} is the current directory")
            if os.path.exists(normalized_dst):
                raise FSError(f"Destination path {normalized_dst} exists")
            else:
                raise FSError(f"Destination path {normalized_dst} not found")

        # Move or rename
        if normalized_dst == normalized_src:
            raise FSError(f"Destination path {normalized_dst} is the same as source path {normalized_src}")

        if os.path.isdir(normalized_dst):
            target = os.path.join(normalized_dst, os.path.basename(normalized_src))
        else:
            target = normalized_dst

        if os.path.exists(target):
            raise FSError(f"Target path {target} already exists")

        if os.path.exists(normalized_src):
            if os.path.isdir(normalized_src):
                shutil.move(normalized_src, target)
            else:
                shutil.move(normalized_src, target)
        else:
            raise FSError(f"Source path {normalized_src} not found")

    def find(self, path='.', pattern='*'):
        """Find all paths matching a glob pattern. Raises errors as specified."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            raise FSError(f"Invalid path: {normalized_path}")

        # Check if the path is a directory
        if not os.path.isdir(normalized_path):
            raise FSError(f"Path {normalized_path} is not a directory")

        # Find all paths matching the pattern
        results = []
        for entry in os.listdir(normalized_path):
            entry_path = os.path.join(normalized_path, entry)
            if os.path.isfile(entry_path):
                if fnmatch.fnmatchcase(entry, pattern):
                    results.append(entry_path)
            elif os.path.isdir(entry_path):
                if fnmatch.fnmatchcase(entry, pattern):
                    results.append(entry_path)

        return results

    def exists(self, path):
        """Check if a path exists. Never raises."""
        if not path:
            return False

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            return False

        return os.path.exists(normalized_path)

    def is_dir(self, path):
        """Check if a path is a directory. Never raises."""
        if not path:
            return False

        # Normalize path
        normalized_path = normalize(path, self.current_dir)

        # Check if the path is valid
        if not normalized_path:
            return False

        return os.path.isdir(normalized_path)
