import shlex
from pathlib import Path
from typing import Any, List, Tuple, Dict, Optional, Set, Union

# The shell wrapper
class Shell:
    """A shell that interacts with an in-memory filesystem."""
    def __init__(self, fs=None):
        self.fs = fs if fs is not None else FileSystem()
        self.current_dir = self.fs.current_dir

    def run(self, script):
        """Run a script and return output and status."""
        if not script:
            raise ValueError("Script cannot be empty")

        # Split the script into lines
        lines = []
        for line in script.split('\n'):
            line = line.strip()
            if not line:
                continue
            if line.startswith('#'):
                continue
            lines.append(line)

        # Process each line
        output = []
        status = 0
        for line_number, line in enumerate(lines, 1):
            parts = shlex.split(line)
            if not parts:
                continue

            command = parts[0]
            if command == 'pwd':
                output.append(self.fs.pwd())
                continue
            elif command == 'cd':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                try:
                    self.fs.cd(path)
                except FSError as e:
                    output.append(f"line {line_number}: cd: {str(e)}\n")
                    status = 1
            elif command == 'mkdir':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                try:
                    self.fs.mkdir(path, parents=True)
                except FSError as e:
                    output.append(f"line {line_number}: mkdir: {str(e)}\n")
                    status = 1
            elif command == 'ls':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                try:
                    entries = self.fs.ls(path)
                    output.append(entries + '\n')
                except FSError as e:
                    output.append(f"line {line_number}: ls: {str(e)}\n")
                    status = 1
            elif command == 'rm':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                try:
                    self.fs.rm(path, recursive=True)
                except FSError as e:
                    output.append(f"line {line_number}: rm: {str(e)}\n")
                    status = 1
            elif command == 'mv':
                if len(parts) == 1:
                    src = parts[0]
                else:
                    src = ' '.join(parts[1:])
                dst = parts[0]
                try:
                    self.fs.mv(src, dst)
                except FSError as e:
                    output.append(f"line {line_number}: mv: {str(e)}\n")
                    status = 1
            elif command == 'write':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                if len(parts) == 2:
                    text = parts[1]
                else:
                    text = ' '.join(parts[2:])
                try:
                    self.fs.write(path, text, append=False)
                except FSError as e:
                    output.append(f"line {line_number}: write: {str(e)}\n")
                    status = 1
            elif command == 'append':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                if len(parts) == 2:
                    text = parts[1]
                else:
                    text = ' '.join(parts[2:])
                try:
                    self.fs.write(path, text, append=True)
                except FSError as e:
                    output.append(f"line {line_number}: append: {str(e)}\n")
                    status = 1
            elif command == 'cat':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                try:
                    output.append(self.fs.read(path) + '\n')
                except FSError as e:
                    output.append(f"line {line_number}: cat: {str(e)}\n")
                    status = 1
            elif command == 'find':
                if len(parts) == 1:
                    path = parts[0]
                else:
                    path = ' '.join(parts[1:])
                pattern = parts[2] if len(parts) > 2 else '*'
                try:
                    results = self.fs.find(path, pattern)
                    output.append('\n'.join(results) + '\n')
                except FSError as e:
                    output.append(f"line {line_number}: find: {str(e)}\n")
                    status = 1
            else:
                # Unknown command
                output.append(f"line {line_number}: COMMAND: unknown command\n")
                status = 2
        return (''.join(output), status)
