# jobs/queue.py
from dataclasses import dataclass
from typing import Optional, Tuple, Dict, List, Any
from collections import deque

@dataclass(frozen=True)
class Job:
    id: int
    payload: Any
    status: str
    attempts: int
    available_at: float
    last_error: Optional[str]

@dataclass(frozen=True)
class JobQueue:
    clock: Callable[[], float]

    def __init__(self, clock: Callable[[], float]):
        self._queue = deque()
        self._clock = clock
        self._dead_letters = []

    def submit(self, job_id: int, payload: Any, delay: float = 0.0) -> Optional[Job]:
        if delay < 0:
            raise ValueError("Delay cannot be negative")
        if job_id < 0:
            raise ValueError("Job ID cannot be negative")
        available_at = self._clock() + delay
        job = Job(id=job_id, payload=payload, status="pending", attempts=0, available_at=available_at, last_error=None)
        self._queue.append(job)
        return job

    def claim(self) -> Optional[Job]:
        # Find the earliest available job
        while self._queue:
            job = self._queue.popleft()
            if job.available_at <= self._clock():
                job.status = "running"
                job.attempts += 1
                return job
        return None

    def complete(self, job_id: int) -> None:
        for job in self._queue:
            if job.id == job_id:
                job.status = "done"
                break

    def retry(self, job_id: int, error: str, at: float) -> None:
        for job in self._queue:
            if job.id == job_id:
                job.status = "pending"
                job.available_at = at
                job.last_error = error
                break

    def bury(self, job_id: int, error: str) -> None:
        for job in self._queue:
            if job.id == job_id:
                job.status = "dead"
                job.last_error = error
                self._dead_letters.append(job)
                break

    def get(self, job_id: int) -> Optional[Job]:
        for job in self._queue:
            if job.id == job_id:
                return job
        return None

    def dead_letters(self) -> List[Job]:
        return self._dead_letters

    def counts(self) -> Dict[str, int]:
        return {
            "pending": sum(1 for job in self._queue if job.status == "pending"),
            "running": sum(1 for job in self._queue if job.status == "running"),
            "done": sum(1 for job in self._queue if job.status == "done"),
            "dead": len(self._dead_letters),
        }

    def next_available(self) -> Optional[float]:
        for job in self._queue:
            if job.status == "pending" and job.available_at <= self._clock():
                return job.available_at
        return None
