# jobs/worker.py
from dataclasses import dataclass
from typing import Optional, Tuple, Any, Callable
from collections import deque
import random

@dataclass(frozen=True)
class Event:
    time: float
    worker: str
    job_id: int
    attempt: int
    outcome: str
    delay: Optional[float]

@dataclass(frozen=True)
class ManualClock:
    _current: float = 0.0

    def __call__(self) -> float:
        return self._current

    def advance(self, dt: float) -> None:
        if dt < 0:
            raise ValueError("Cannot advance time by a negative delta")
        self._current += dt

    def set(self, t: float) -> None:
        if t < self._current:
            raise ValueError("Cannot set time to a value earlier than current")
        self._current = t

class Worker:
    def __init__(self, name: str, queue: JobQueue, handler: Callable[[Any], Any], policy: RetryPolicy, rng: random.Random, clock: Callable[[], float]):
        self.name = name
        self.queue = queue
        self.handler = handler
        self.policy = policy
        self.rng = rng
        self.clock = clock
        self._events = deque()

    def step(self) -> Optional[Event]:
        # Claim a job
        job = self.queue.claim()
        if not job:
            return None

        # Execute the handler
        try:
            result = self.handler(job.payload)
            if result is not None:
                # Job completed
                job.status = "done"
                return Event(time=self.clock(), worker=self.name, job_id=job.id, attempt=job.attempts, outcome="done", delay=None)
            else:
                # Job was not completed, but we're in a loop
                return None
        except PermanentError:
            # Job buried
            job.status = "dead"
            job.last_error = "PermanentError"
            return Event(time=self.clock(), worker=self.name, job_id=job.id, attempt=job.attempts, outcome="dead", delay=None)
        except Exception as exc:
            # Job failed and should be retried
            if self.policy.should_retry(job.attempts):
                delay = self.policy.delay(job.attempts, self.rng)
                job.status = "pending"
                job.available_at = self.clock() + delay
                job.last_error = f"{type(exc).__name__}: {exc}"
                return Event(time=self.clock(), worker=self.name, job_id=job.id, attempt=job.attempts, outcome="retry", delay=delay)
            else:
                # Job buried
                job.status = "dead"
                job.last_error = f"{type(exc).__name__}: {exc}"
                return Event(time=self.clock(), worker=self.name, job_id=job.id, attempt=job.attempts, outcome="dead", delay=None)

    def run_until_idle(self, queue: JobQueue, workers: List[Worker], clock: Callable[[], float], max_steps: int = 10000) -> List[Event]:
        events = []
        for _ in range(max_steps):
            for worker in workers:
                event = worker.step()
                if event:
                    events.append(event)
                    if event.outcome == "dead":
                        # Add to dead letters
                        queue.bury(event.job_id, event.last_error)
                    elif event.outcome == "retry":
                        # Retry the job
                        queue.retry(event.job_id, event.last_error, event.delay)
                    elif event.outcome == "done":
                        # Complete the job
                        queue.complete(event.job_id)
            if not events:
                # No events in this round, check if queue is empty
                if queue.next_available() is None:
                    break
                # Set clock to the next available time
                clock(queue.set(queue.next_available()))
        return events
