class Exact:
    shares: Dict[str, int]

@dataclass(frozen=True)
class Percent:
    shares: Dict[str, int]

def parse_amount(text: str) -> int:
    if not text:
        raise ValueError("Amount cannot be empty")

    # Handle negative numbers
    if text[0] == '-':
        sign = -1
        text = text[1:]
    else:
        sign = 1

    # Split into integer and decimal parts
    parts = text.split('.')
    if len(parts) == 1:
        decimal_part = '00'
    else:
        decimal_part = parts[1]

    # Ensure decimal part has exactly two digits
    if len(decimal_part) < 2:
        decimal_part += '0' * (2 - len(decimal_part))

    # Convert to cents
    amount_str = f"{sign}{parts[0]}.{decimal_part}"
    cents = int(amount_str.replace('.', ''))

    if cents < 0:
        raise ValueError("Amount cannot be negative")

    return cents

def format_amount(cents: int) -> str:
    if cents == 0:
        return "0.00"

    # Handle negative amounts
    if cents < 0:
        sign = '-'
        cents = -cents
    else:
        sign = ''

    # Split into integer and decimal parts
    integer_part = cents // 100
    decimal_part = (cents % 100) // 10
    remainder = cents % 10

    # Format decimal part with exactly two digits
    decimal_str = f"{decimal_part:02d}"
    if remainder > 0:
        decimal_str += f"{remainder:01d}"

    return f"{sign}{integer_part}.{decimal_str}"
