from .model import Group, Expense
from typing import Dict, List, Optional

def balances(group: Group) -> Dict[str, int]:
    # Initialize balances
    balances = {member: 0 for member in group.members}

    # Process expenses
    for expense in group.expenses:
        paid_by = expense.paid_by
        amount = expense.amount
        split = expense.split

        # Calculate shares
        if split == Equal:
            n = len(group.members)
            shares = {member: amount // n for member in group.members}
            remainder = amount % n
            for i in range(n):
                member = group.members[i]
                if remainder > 0:
                    shares[member] += remainder
                    remainder -= 1
        elif split == Exact:
            shares = expense.split
        elif split == Percent:
            shares = expense.split

        # Update balances
        for member, share in shares.items():
            balances[member] += share

    # Process payments
    for payment in group.payments:
        payer = payment.payer
        payee = payment.payee
        amount = payment.amount

        balances[payer] -= amount
        balances[payee] += amount

    return balances

def format_balances(bals: Dict[str, int]) -> str:
    lines = []
    for member in sorted(bals.keys()):
        amount = bals[member]
        if amount > 0:
            lines.append(f"+{format_amount(amount)}")
        elif amount < 0:
            lines.append(f"-{format_amount(abs(amount))}")
        else:
            lines.append("0.00")
    return "\n".join(lines)
