# split/settle.py
from typing import Dict, List, Optional
from dataclasses import.namedtuple

Transfer = namedtuple('Transfer', ['payer', 'payee', 'amount'])

def settle(bals: Dict[str, int]) -> List[Transfer]:
    # Check if balances sum to zero
    if sum(bals.values()) != 0:
        raise ValueError("Balances do not sum to zero")

    # Get members in alphabetical order
    members = sorted(bals.keys())

    # Create a list to store transfers
    transfers = []

    # Find the creditor with the largest positive balance
    while True:
        # Find the creditor with the largest positive balance
        creditor = None
        max_balance = -1
        for member in members:
            if bals[member] > max_balance:
                max_balance = bals[member]
                creditor = member

        if not creditor:
            break

        # Find the debtor with the most negative balance
        debtor = None
        min_balance = float('inf')
        for member in members:
            if bals[member] < min_balance:
                min_balance = bals[member]
                debtor = member

        if not debtor:
            break

        # Calculate the amount to transfer
        amount = min(abs(bals[creditor]), abs(bals[debtor]))

        # Perform the transfer
        transfers.append(Transfer(creditor, debtor, amount))

        # Update balances
        bals[creditor] -= amount
        bals[debtor] += amount

    return transfers

def format_plan(transfers: List[Transfer]) -> str:
    if not transfers:
        return "All settled.\n"

    result = []
    for transfer in transfers:
        amount = transfer.amount
        formatted_amount = format_amount(amount)
        result.append(f"{transfer.payer} pays {transfer.payee} {formatted_amount}")

    return "\n".join(result)
